-- Generated by scripts/gen-seed.ts. Do not edit by hand.
-- Content version 1. Machine MK, every catalog row loaded as draft.
-- Idempotent: ON CONFLICT updates only rows that an admin has not touched
-- (spots/routes.updated_by is null). Re-running never overwrites those edits.
-- vodoca-monastery is included as a draft. Coordinates come from src/data/spots.ts
-- (41.4506, 22.5903) and still need Dev Content review. See seed-report.json.

create or replace function public.apply_content_seed_v1()
returns void
language plpgsql
security definer
set search_path = public
as $seed$
begin
  insert into public.spots (
    slug, region, tags, lat, lng,
    name_mk, name_en, description_mk, description_en,
    long_description_mk, long_description_en, tagline_mk, tagline_en,
    rider_tips_mk, rider_tips_en, status, sort_order, mk_status
  )
  values
(
    $sr$galicica-pass$sr$,
    $sr$West$sr$::public.region,
    array[$sr$Views$sr$, $sr$Roads$sr$, $sr$Mountain$sr$]::text[],
    40.95,
    20.8,
    $sr$Превој Галичица$sr$,
    $sr$Galicica Pass$sr$,
    $sr$Каде што асфалтот се вие низ облаците, а две древни езера го огледуваат небото.$sr$,
    $sr$Where asphalt serpentines through clouds, and two ancient lakes mirror the infinite sky below.$sr$,
    $sr$Меѓу небото и длабоката сина вода лежи Галичица — превој што не спојува само две езера, туку две состојби. Моторот пее низ секоја фиока: Охридското Езеро блеска како сафир, а Преспанското сонува во тивок смарагд. Висината го зема здивот, погледот зема нешто подлабоко. Тука, каде што орлите кружат под тркалата, возачот станува аџија.$sr$,
    $sr$Between heaven and the deep blue waters lies Galicica—a pass that doesn't merely connect two lakes, but two states of being. As your engine hums through each hairpin turn, Lake Ohrid glimmers on one side like liquid sapphire, while Lake Prespa dreams in quiet emerald on the other. The altitude steals your breath, but the vistas steal something deeper. Here, where eagles circle below your wheels and clouds kiss the tarmac, you understand why the ancients believed mountains were bridges to the divine. Every curve earned, every summit gained—this is where riders become pilgrims.$sr$,
    $sr$Каде што патот го среќава небото$sr$,
    $sr$Where the road meets the heavens$sr$,
    array[$sr$Во зори маглата се плете меѓу врвовите$sr$, $sr$На излезите од фиоките има растресит чакал — наведнувај се со почит$sr$, $sr$Кафулето на врвот служи турско кафе доволно силно за висината$sr$]::text[],
    array[$sr$Dawn rides offer mystical mist that weaves between peaks like spirits dancing$sr$, $sr$Loose gravel haunts the hairpin exits—lean with respect, not recklessness$sr$, $sr$The summit café serves Turkish coffee strong enough to match the altitude$sr$]::text[],
    $sr$draft$sr$::public.publish_status,
    1,
    $sr$machine$sr$::public.translation_status
  ),
(
    $sr$vevcani-village$sr$,
    $sr$West$sr$::public.region,
    array[$sr$Hidden Gem$sr$, $sr$Nature$sr$, $sr$Cultural$sr$]::text[],
    41.24,
    20.59,
    $sr$Село Вевчани$sr$,
    $sr$Vevčani Village$sr$,
    $sr$Древна република каде што изворите пеат под илјадагодишни дабови, а времето тече како мед.$sr$,
    $sr$An ancient republic where crystal springs sing beneath thousand-year oaks, and time moves like honey.$sr$,
    $sr$Некои места живеат надвор од времето, и Вевчани е такво засолниште. Оваа самопрогласена република — да, има свој пасош — чува извори толку чисти што ги напиле цареви и бунтовници. Патот се стеснува и те тера да забавиш: мов по камењата, бескрајната песна на водата, светлина низ шумата. Мештаните сè уште зборуваат за водни духови. Шумата тука дише.$sr$,
    $sr$Some places exist outside of time, and Vevčani is one such sanctuary. This self-declared republic—yes, it has its own passport—guards springs so pure they've quenched the thirst of emperors and rebels alike. The road narrows as you approach, forcing you to slow, to notice: the moss-covered stones, the water's endless song, the forest canopy filtering light into emerald cathedral rays. Locals still speak of water spirits and mountain guardians, and as the springs cascade over ancient rock, you'll understand this isn't superstition—it's recognition. The forest breathes here. And if you listen closely, it whispers secrets in languages older than roads.$sr$,
    $sr$Каде што водата шепоти древни тајни$sr$,
    $sr$Where water whispers ancient secrets$sr$,
    array[$sr$Јануарскиот карневал го претвора селото во сон од маски и оган$sr$, $sr$Приближи се до изворите во тишина — некои води бараат почит$sr$, $sr$Крчмите крај реката служат пастрмка што пливала пред малку$sr$]::text[],
    array[$sr$January's carnival transforms the village into a surreal dream of masks and fire$sr$, $sr$Approach the springs in silence—some waters demand reverence$sr$, $sr$The riverside taverns serve trout that was swimming moments before it reached your plate$sr$]::text[],
    $sr$draft$sr$::public.publish_status,
    2,
    $sr$machine$sr$::public.translation_status
  ),
(
    $sr$mavrovo-lake-loop$sr$,
    $sr$West$sr$::public.region,
    array[$sr$Views$sr$, $sr$Roads$sr$, $sr$Nature$sr$]::text[],
    41.65,
    20.73,
    $sr$Круг околу Мавровско Езеро$sr$,
    $sr$Mavrovo Lake Loop$sr$,
    $sr$Километри со мирис на бор, каде што потоната црква се издига од азурна вода.$sr$,
    $sr$Pine-scented kilometers where a drowned church rises from azure waters, and every season tells a different story.$sr$,
    $sr$Маврово не е еден пат, туку медитација — круг што учи трпение. Под површината на езерото спие црква, а нејзиниот крст стои над водата како молитва што одбила да се удави. Летос боровите издишуваат стар мирис, есента ги пали планините, зимата сè претвора во кристална тишина. Ова не е рута за брзање. Ова е рута да се сетите кој сте кога светот престанува да ве брза.$sr$,
    $sr$Mavrovo is not one road but a meditation—a loop that teaches the rider patience, presence, and the profound beauty of going nowhere in particular. The lake itself holds a secret: beneath its surface sleeps a church, its cross rising above the waterline like a prayer that refused to drown. In summer, the pines exhale their ancient perfume; in autumn, the mountains blaze with color so vivid it seems painted by a divine hand; in winter, ice transforms everything into crystalline silence. The road follows the water's edge, curves around hidden coves, climbs through forests that have watched centuries pass. This is not a route to rush. This is a route to remember who you are when the world stops rushing you.$sr$,
    $sr$Каде што спомените излегуваат од длабочината$sr$,
    $sr$Where memories surface from the deep$sr$,
    array[$sr$Целиот круг бара два часа без застанување — но кој вози Маврово без да застане?$sr$, $sr$Октомвриските бои тука се мерат со која било шума на светот$sr$, $sr$Наполнете резервоар во Маврови Анови — планините немаат пумпи$sr$]::text[],
    array[$sr$The full loop demands two hours without stops—but who rides Mavrovo without stopping?$sr$, $sr$October's colors here rival any forest on Earth$sr$, $sr$Fill your tank in Mavrovi Anovi—the mountains keep no fuel stations$sr$]::text[],
    $sr$draft$sr$::public.publish_status,
    3,
    $sr$machine$sr$::public.translation_status
  ),
(
    $sr$trpejca-beach$sr$,
    $sr$West$sr$::public.region,
    array[$sr$Views$sr$, $sr$Food Stops$sr$, $sr$Nature$sr$]::text[],
    41.03,
    20.75,
    $sr$Плажа Трпејца$sr$,
    $sr$Trpejca Beach$sr$,
    $sr$Крајезерско село каде што мрежите се сушат на средоземно сонце, а времето се топи во бранови.$sr$,
    $sr$A lakeside village where fishermen's nets dry in Mediterranean sun, and time dissolves into the rhythm of gentle waves.$sr$,
    $sr$Трпејца ја викаат македонски Сен Тропе, но тоа ја промашува поентата. Ова не е сјај — ова е благодат. Камени куќи се тркалаат кон Охридското Езеро. Рибарите крпат мрежи со вештини непроменети со векови. Воздухот мириса на скара и диви билки. Патот вие низ маслинки и покрај византиски цркви. На брегот водата е доволно бистра за да се избројат рибите. Нарачајте го уловот на денот и оставете ги брановите да ве научат на нивниот ритам.$sr$,
    $sr$They call Trpejca 'the Macedonian Saint-Tropez,' but that misses the point entirely. This isn't glamour—it's grace. Stone houses tumble toward Lake Ohrid's shore like children rushing to the water's edge. Fishermen mend nets using techniques unchanged for centuries. The air smells of grilling fish and wild herbs. The road here winds through olive groves and past Byzantine churches whose frescoes have witnessed a millennium of sunsets. At the shore, you'll find pebbles smooth enough to sleep on, water clear enough to count fish at depth, and a pace of life that reminds you urgency is a modern invention. Order the catch of the day. Watch the sun melt into the lake. Let the waves teach you their ancient, patient rhythm.$sr$,
    $sr$Каде што душата учи да лебди$sr$,
    $sr$Where the soul learns to float$sr$,
    array[$sr$Селските улички ја тестираат бавната вожња — прифатете го предизвикот$sr$, $sr$Летникот на скара не бара ништо освен поглед на езерото$sr$, $sr$Залезот тука не е изборен — тоа е одржување на душата$sr$]::text[],
    array[$sr$The village streets test your slow-speed skills—embrace the challenge$sr$, $sr$Letnik fish, grilled simply, needs no accompaniment but lake views$sr$, $sr$Sunset here isn't optional—it's mandatory maintenance for the soul$sr$]::text[],
    $sr$draft$sr$::public.publish_status,
    4,
    $sr$machine$sr$::public.translation_status
  ),
(
    $sr$pelister-viewpoint$sr$,
    $sr$West$sr$::public.region,
    array[$sr$Views$sr$, $sr$Roads$sr$, $sr$Mountain$sr$]::text[],
    41,
    21.19,
    $sr$Видиковец Пелистер$sr$,
    $sr$Pelister Viewpoint$sr$,
    $sr$Каде што Баба Планина го среќава небото, а древните борови стојат како сведоци.$sr$,
    $sr$Where Baba Mountain meets the sky, ancient pines stand witness, and the horizon curves with the weight of wonder.$sr$,
    $sr$Пелистер е првиот национален парк во Македонија, но бројките не му прават правда. Тука ендемскиот молика — бор што речиси никаде на друго место не расте — стои пет милиони години. Патот се качува без милост, низ шуми што шепотат на ветрови од целиот Балкан. Од видиковецот се гледа Грција на југ, езерата на запад, рамнини кон хоризонти што никогаш нема да ги стигнете. Некои височини не се мерат во метри.$sr$,
    $sr$Pelister is Macedonia's first national park, but numbers and designations fail it. This is where the endemic Molika pine—found nowhere else on Earth—has stood for five million years, watching ice ages come and go, watching civilizations rise and fall, watching riders like you seek something that only altitude and solitude can provide. The road climbs relentlessly, switching back through forests that whisper in winds that have crossed the entire Balkan peninsula. At the viewpoint, you'll understand why ancient peoples believed their gods lived on mountaintops. The world spreads below you—Greece to the south, the lakes to the west, plains stretching toward horizons you'll never reach. Some heights cannot be measured in meters. Some views cannot be captured in photographs. Some silences speak louder than any words ever could.$sr$,
    $sr$Каде што висината станува став$sr$,
    $sr$Where altitude becomes attitude$sr$,
    array[$sr$Планинското време пишува свои правила — носете слоеви и во лето$sr$, $sr$Ледничките езера ги наградуваат оние што пешачат понатаму од патот$sr$, $sr$Во август дивите бобинки се покрај патот — природна ужина$sr$]::text[],
    array[$sr$Mountain weather writes its own rules—pack layers even in summer$sr$, $sr$The glacial lakes reward those willing to hike beyond the road's end$sr$, $sr$August's wild berries line the roadside—nature's pit stop provisions$sr$]::text[],
    $sr$draft$sr$::public.publish_status,
    5,
    $sr$machine$sr$::public.translation_status
  ),
(
    $sr$prespa-lake-shore$sr$,
    $sr$West$sr$::public.region,
    array[$sr$Views$sr$, $sr$Nature$sr$, $sr$Hidden Gem$sr$]::text[],
    40.92,
    21,
    $sr$Брег на Преспанско Езеро$sr$,
    $sr$Prespa Lake Shore$sr$,
    $sr$Тивки води каде што пеликаните лизгаат низ утринска магла, а границите се топат.$sr$,
    $sr$Quiet waters where pelicans glide through morning mist and borders dissolve into shared horizons.$sr$,
    $sr$Преспа е срамежливата сестра на славниот Охрид — поретко посетена, поранлива, потаинствена. Три држави ја делат водата: Северна Македонија, Албанија и Грција. Пеликаните на островите не познаваат граници, ниту тишината во зори. Патот го следи брегот низ јаболкници и напуштени села, покрај византиски цркви зад обраснати ѕидови. Преспа не бара ништо од вас освен внимание.$sr$,
    $sr$Prespa is the shy sibling of famous Ohrid—less visited, more vulnerable, infinitely more mysterious. Three countries share these waters: North Macedonia, Albania, Greece. But the pelicans that nest on its islands recognize no borders, and neither does the profound stillness that settles over the lake at dawn. The road traces the shoreline through apple orchards and abandoned villages, past Byzantine churches hiding behind overgrown walls, through communities where time flows differently. Unlike its popular neighbor, Prespa asks nothing of you but attention. Watch the water birds paint circles in the sky. Listen to the reeds whisper secrets passed between nations. Feel the peculiar peace of a place the world hasn't yet discovered—or perhaps has wisely left alone.$sr$,
    $sr$Каде што три народи делат една душа$sr$,
    $sr$Where three nations share one soul$sr$,
    array[$sr$Зората носи лет на пеликани — трпението го наградува раниот возач$sr$, $sr$Пограничните села служат планинска кујна недопрена од туризам$sr$, $sr$Есента ги бои јаболкниците во бои што вредат за свртување$sr$]::text[],
    array[$sr$Dawn brings pelican flights—patience rewards the early rider$sr$, $sr$The border villages serve authentic mountain cuisine untouched by tourism$sr$, $sr$Autumn paints the apple orchards in colors worth the detour$sr$]::text[],
    $sr$draft$sr$::public.publish_status,
    6,
    $sr$machine$sr$::public.translation_status
  ),
(
    $sr$ohrid-old-town-overlook$sr$,
    $sr$West$sr$::public.region,
    array[$sr$Views$sr$, $sr$Cultural$sr$, $sr$Food Stops$sr$]::text[],
    41.11,
    20.8,
    $sr$Видиковец на стариот Охрид$sr$,
    $sr$Ohrid Old Town Overlook$sr$,
    $sr$Древни камења на цареви гледаат кон води што виделе триесет века човечки соништа.$sr$,
    $sr$Ancient stones stacked by emperors gaze upon waters that have witnessed thirty centuries of human dreams.$sr$,
    $sr$Охрид го викаат Ерусалим на Балканот, и од тврдината над стариот град се разбира зошто. Секој камен има приказна. Патот се вие низ калдрма измазнета од милениуми, покрај цркви постари од повеќето држави, до Самуиловата тврдина каде што погледот го запира срцето. Охридското Езеро се простира долу како течно време — едно од најстарите и најдлабоките езера во Европа. Паркирајте. Останатите скалила искачете пеш.$sr$,
    $sr$They call Ohrid the Jerusalem of the Balkans, and from the fortress overlooking the old town, you understand why. Every stone here has a story. Every narrow lane has heard footsteps of Romans, Byzantines, Ottomans, and now—you. The road winds through cobblestones polished by millennia of passage, past churches older than most nations, up to Samuel's Fortress where the view stops hearts and starts conversations with the cosmos. Lake Ohrid stretches below like liquid time itself—one of Europe's oldest and deepest lakes, home to species found nowhere else on Earth. The old town cascades down the hillside, a tumble of terracotta roofs and whitewashed walls that seem to glow at golden hour. Park the bike. Climb the remaining steps on foot. Let the view remind you that empires rise and fall, but some beauties endure forever.$sr$,
    $sr$Каде што историјата ја среќава вечноста$sr$,
    $sr$Where history meets eternity$sr$,
    array[$sr$Залезот од тврдината го топи езерото во злато — дојдете порано за место$sr$, $sr$Калдрмата во стариот град бара бавна брзина и големо внимание$sr$, $sr$Винските подруми се кријат по дворови — прашајте ги мештаните$sr$]::text[],
    array[$sr$Sunset from the fortress turns the lake into molten gold—arrive early for the best perch$sr$, $sr$The old town's cobblestones demand slow speeds and high appreciation$sr$, $sr$Local wine taverns hide in courtyards—ask locals for their secret favorites$sr$]::text[],
    $sr$draft$sr$::public.publish_status,
    7,
    $sr$machine$sr$::public.translation_status
  ),
(
    $sr$bistra-mountain-pass$sr$,
    $sr$West$sr$::public.region,
    array[$sr$Roads$sr$, $sr$Adventure$sr$, $sr$Mountain$sr$]::text[],
    41.62,
    20.58,
    $sr$Превој на Бистра$sr$,
    $sr$Bistra Mountain Pass$sr$,
    $sr$Високи свиоци низ дивина толку чиста што памети што значела слободата пред патиштата.$sr$,
    $sr$High-altitude twists through wilderness so pure it remembers what freedom meant before roads existed.$sr$,
    $sr$Бистра не ги пречекува посетителите — ги трпи. Ова е нескротеното срце на Македонија, каде што волците сè уште ловат, а овчарите ја знаат секоја ѕвезда по име. Превојот сече низ терен што се борел против патот. Фиоки без ограда нудат погледи што истовремено понижуваат и возбудуваат. Воздухот се разредува, сетилата се изоструваат. Ова е возење во најгола форма: машина, пат, планина и тесниот простор каде што се среќаваат.$sr$,
    $sr$Bistra doesn't welcome visitors—it tolerates them. This is Macedonia's untamed heart, where wolves still hunt and shepherds still know every star by name. The pass cuts through terrain that fought against the road's construction and continues to challenge its existence. Hairpins carved into mountainsides offer views that simultaneously humble and exhilarate. No guardrails here—just ancient stone markers placed by travelers who understood that some journeys require respect for risk. The air thins as you climb, sharpening every sense. Eagles circle thermals above exposed granite faces. The engine's note changes with altitude, becoming part of a symphony that includes wind, wildlife, and the profound silence between heartbeats. This is riding at its most elemental—machine, road, mountain, and the narrow space where they meet.$sr$,
    $sr$Каде што дивото сè уште владее$sr$,
    $sr$Where the wild still rules$sr$,
    array[$sr$Времето се менува без предупредување — водоотпорното не е избор, туку опрема$sr$, $sr$Планинските колиби служат јагне на тивок оган$sr$, $sr$Почитувајте го правото на патот на овчарите — стадата ги поседуваат овие патишта по потекло$sr$]::text[],
    array[$sr$Weather shifts without warning—waterproofs aren't optional, they're survival gear$sr$, $sr$The mountain huts serve lamb slow-cooked over fires that never quite die$sr$, $sr$Respect the shepherds' right of way—their flocks own these roads by ancestry$sr$]::text[],
    $sr$draft$sr$::public.publish_status,
    8,
    $sr$machine$sr$::public.translation_status
  ),
(
    $sr$sv-naum-monastery$sr$,
    $sr$West$sr$::public.region,
    array[$sr$Cultural$sr$, $sr$Nature$sr$, $sr$Views$sr$]::text[],
    40.91,
    20.74,
    $sr$Манастир Св. Наум$sr$,
    $sr$Sv. Naum Monastery$sr$,
    $sr$Духовно засолниште крај езерото, каде што пауни шетаат, а извори избиваат од легенда.$sr$,
    $sr$Lakeside spiritual oasis where peacocks roam ancient grounds and springs bubble up from the depths of legend.$sr$,
    $sr$На јужниот раб на Охридското Езеро, каде што завршува Северна Македонија и почнува Албанија, стои еден од најволшебните манастири на Балканот. Свети Наум го основал пред повеќе од илјада години, и неговиот дух сè уште како да ги движи пауните во градините и изворите што го хранат езерото. Патот го следи брегот. Бродови ве носат до изворите каде што тиркизната вода излегува од земјата како течен скапоцен камен. Мештаните велат дека ако го прислоните увото на гробот, сè уште му се слуша срцето.$sr$,
    $sr$At the southern edge of Lake Ohrid, where North Macedonia ends and Albania begins, stands one of the Balkans' most enchanting monasteries. Saint Naum founded this sanctuary over a millennium ago, and his spirit still seems to animate every peacock that struts through the gardens, every spring that bubbles up from the underground river feeding the lake. The road here follows the lakeshore through landscapes that defy season—lush in summer, golden in autumn, hauntingly beautiful under winter snow. At the monastery, boat rides take you to the springs where turquoise waters emerge from the earth like liquid gemstones. The church holds the saint's tomb, and locals swear that pressing your ear to the stone lets you hear his heartbeat still echoing across centuries.$sr$,
    $sr$Каде што небото го допира брегот$sr$,
    $sr$Where heaven touches the shore$sr$,
    array[$sr$Возењето со брод до изворите вреди — дојдете рано, пред групите$sr$, $sr$Пауните се територијални — гледајте од почитливо растојание$sr$, $sr$Ресторанот над езерото служи пастрмка уловена тоа утро$sr$]::text[],
    array[$sr$The springs boat ride is worth every moment—arrive early to beat tour groups$sr$, $sr$Peacocks are territorial—admire from a respectful distance$sr$, $sr$The restaurant overlooking the lake serves trout so fresh it was swimming that morning$sr$]::text[],
    $sr$draft$sr$::public.publish_status,
    9,
    $sr$machine$sr$::public.translation_status
  ),
(
    $sr$golem-grad-island$sr$,
    $sr$West$sr$::public.region,
    array[$sr$Adventure$sr$, $sr$Nature$sr$, $sr$Hidden Gem$sr$]::text[],
    40.87,
    20.98,
    $sr$Остров Голем Град$sr$,
    $sr$Golem Grad Island$sr$,
    $sr$Таинствен змиски остров во Преспа, со римски урнатини и диви чувари.$sr$,
    $sr$Mysterious snake island rising from Prespa's waters, holding Roman ruins and wild reptilian guardians.$sr$,
    $sr$Голем Град се издига од Преспанското Езеро како сон од камен. Ненаселениот остров чува римски урнатини, византиски базилики и змии што владеат тука со векови. Патот до испловувањето вие низ јаболкници и рибарски села замрзнати во време. На брегот одите меѓу храмови и безброј змии што имаат старо право на престој. Ова е природа што го враќа она што човекот го напуштил.$sr$,
    $sr$Rising from Lake Prespa like a dream made stone, Golem Grad—the Great City—is one of the Balkans' strangest destinations. This uninhabited island holds Roman ruins, Byzantine basilicas, and a population of water snakes that have ruled here undisturbed for centuries. The road to the departure point winds through apple orchards and fishing villages frozen in time. The boat crossing builds anticipation as the island grows larger, revealing forested slopes hiding architectural secrets. Once ashore, you walk among temples where emperors once worshipped, walls where monks once prayed, and countless serpents that slither between stones with an ancient right of residence. This is nature reclaiming what humanity abandoned—a reminder that our monuments are temporary, but the wild always waits.$sr$,
    $sr$Каде што змиите чуваат древни тајни$sr$,
    $sr$Where serpents guard ancient secrets$sr$,
    array[$sr$Бродовите тргнуваат од Коњско или Стење — проверете ја сезонската рамнотежа$sr$, $sr$Змиите се безопасни, но многубројни — носете затворени чевли$sr$, $sr$Понесете вода и храна — на островот нема ништо$sr$]::text[],
    array[$sr$Boats depart from Konjsko or Stenje—check seasonal schedules in advance$sr$, $sr$The snakes are harmless but numerous—wear closed shoes and watch your step$sr$, $sr$Bring water and snacks—the island has no facilities whatsoever$sr$]::text[],
    $sr$draft$sr$::public.publish_status,
    10,
    $sr$machine$sr$::public.translation_status
  ),
(
    $sr$matka-canyon$sr$,
    $sr$Central$sr$::public.region,
    array[$sr$Views$sr$, $sr$Cultural$sr$, $sr$Adventure$sr$]::text[],
    41.95,
    21.3,
    $sr$Кањон Матка$sr$,
    $sr$Matka Canyon$sr$,
    $sr$Вапненичка катедрала издлабена од вода и време, каде што манастири висат на карпи.$sr$,
    $sr$A limestone cathedral carved by water and time, where monasteries cling to cliffs and caves guard prehistoric secrets.$sr$,
    $sr$Треска поминала милениуми длабејќи ја Матка, и резултатот е геолошка поезија. Карпите се издигаат вертикално од смарагдна вода, со пештери што чуваат пеперутки од леденото доба. Средновековните монаси ги избрале овие невозможни ѕидови за своите манастири. Кога кањонот конечно се открива, единствениот одговор е тишина. Тука се разбира дека природата е првиот и најголемиот архитект.$sr$,
    $sr$The Treska River spent millennia carving Matka Canyon, and the result is nothing short of geological poetry. Cliffs rise vertically from emerald waters, their faces pocked with caves that shelter Ice Age butterflies and stalactites older than civilization. Medieval monks chose these impossible walls for their monasteries, understanding that some devotions require dramatic settings. The road to Matka builds anticipation with each curve—you sense something monumental approaching before you see it. And when the canyon finally reveals itself, when those fortress walls of limestone tower above you, the only response is silence. This is where you understand that nature is the first and greatest architect, and we are merely visitors in her cathedral.$sr$,
    $sr$Каде што каменот ја памети вечноста$sr$,
    $sr$Where stone remembers eternity$sr$,
    array[$sr$Изгрејсонцето ги победува кајакарите и ги бои ѕидовите во злато$sr$, $sr$Бродот во пештерата открива подземен свет од кристал$sr$, $sr$Малите мотори полесно го наоѓаат паркингот; големите бараат трпение$sr$]::text[],
    array[$sr$Sunrise beats the kayak crowds and paints the canyon walls in gold$sr$, $sr$The cave boat tour reveals an underworld of crystalline wonder$sr$, $sr$Small bikes navigate the limited parking with grace; cruisers require patience$sr$]::text[],
    $sr$draft$sr$::public.publish_status,
    11,
    $sr$machine$sr$::public.translation_status
  ),
(
    $sr$treskavec-monastery$sr$,
    $sr$Central$sr$::public.region,
    array[$sr$Cultural$sr$, $sr$Adventure$sr$, $sr$Mountain$sr$]::text[],
    41.28,
    21.35,
    $sr$Манастир Трескавец$sr$,
    $sr$Treskavec Monastery$sr$,
    $sr$Оддалечено искачување каде што древни камења ги пробиваат облаците, а тишината станува јазик.$sr$,
    $sr$A remote ascent where ancient stones pierce the clouds and silence becomes a language unto itself.$sr$,
    $sr$Качен на гола планина како молитва замрзната во камен, Трескавец бара сè од оној што го бара. Патот — ако воопшто може така да се нарече — се вие нагоре низ терен што ги дели љубопитните од посветените. Византиските ѕидови изгледаат како да пораснале од карпата. Фреските внатре сè уште светат со бои измешани од вера и минерал. На врвот ветрот и тишината се натпреваруваат, а Пелагонија се простира невозможно далеку долу.$sr$,
    $sr$Perched atop a barren mountain like a prayer frozen in stone, Treskavec Monastery demands everything from those who seek it. The road—if you can call it that—twists upward through terrain that separates the curious from the committed. Byzantine walls rise from the rock as if grown rather than built, their centuries of devotion weathering storms that would crumble lesser structures. Frescoes inside still glow with colors mixed from faith and mineral, depicting saints who knew that the path to enlightenment is always uphill. At the summit, wind and silence compete for dominance. The Pelagonia plain stretches impossibly far below. Here, at the edge of the sky, you understand why hermits chose hardship over comfort. Some truths only reveal themselves to those willing to climb.$sr$,
    $sr$Каде што верата е издлабена во камен$sr$,
    $sr$Where faith carved into stone$sr$,
    array[$sr$Последните километри бараат гуми за авантура и полно внимание$sr$, $sr$Носете вода — изворите на манастирот пресушуваат во лето$sr$, $sr$Изгрејсонцето ги осветлува фреските со светлината што ја сакале сликарите$sr$]::text[],
    array[$sr$The final kilometers demand adventure-ready tires and unwavering focus$sr$, $sr$Carry water—the monastery's springs run dry in summer$sr$, $sr$Sunrise illuminates the frescoes with light the painters intended$sr$]::text[],
    $sr$draft$sr$::public.publish_status,
    12,
    $sr$machine$sr$::public.translation_status
  ),
(
    $sr$kozjak-lake$sr$,
    $sr$Central$sr$::public.region,
    array[$sr$Nature$sr$, $sr$Views$sr$, $sr$Hidden Gem$sr$]::text[],
    41.98,
    21.28,
    $sr$Езеро Козјак$sr$,
    $sr$Kozjak Lake$sr$,
    $sr$Мирно езеро во див кањон, каде што тиркизната вода ја огледува недопрената планина.$sr$,
    $sr$Serene reservoir nestled in wild canyon country, where turquoise waters mirror untouched mountain wilderness.$sr$,
    $sr$Скриен возводно од Матка, Козјак е потивката страна на долината на Треска. Оваа акумулација, создадена со брана, созреала во нешто неочекувано убаво — тиркизен камен во вапненички ѕидови. Патот е тесен, вијугав, повремено тежок, но секоја внимателна кривина вреди. На работ на водата владее тишина. Повеќето посетители само седат и се чудат како таква убавина се крие толку близу до главниот град.$sr$,
    $sr$Hidden upstream from Matka Canyon, Kozjak Lake represents the quieter, more contemplative side of the Treska River valley. This reservoir, created by a dam that tamed once-wild waters, has evolved into something unexpectedly beautiful—a turquoise gem set in limestone walls that rise like natural fortresses. The road here rewards patient riders: narrow, winding, occasionally challenging, but offering vistas that make every careful turn worthwhile. At the water's edge, silence reigns. Kayakers occasionally disturb the mirror surface, but mostly, this is a place for reflection in both senses. The surrounding cliffs host caves and climbing routes, but most visitors simply sit, gaze at the improbably colored water, and wonder how such beauty hides so close to a capital city.$sr$,
    $sr$Каде што мирот ја одразува бесконечноста$sr$,
    $sr$Where stillness reflects infinity$sr$,
    array[$sr$Патот од Матка продолжува до Козјак — направете двојна тура$sr$, $sr$Раните утра даваат најмирни одрази на водата$sr$, $sr$Пливањето е дозволено на означени места — понесете опрема во лето$sr$]::text[],
    array[$sr$The road from Matka continues to Kozjak—make it a double feature ride$sr$, $sr$Early mornings offer the most mirror-like water reflections$sr$, $sr$Swimming is permitted in designated areas—bring gear in summer$sr$]::text[],
    $sr$draft$sr$::public.publish_status,
    13,
    $sr$machine$sr$::public.translation_status
  ),
(
    $sr$krushevo-paragliding$sr$,
    $sr$Central$sr$::public.region,
    array[$sr$Adventure$sr$, $sr$Views$sr$, $sr$Mountain$sr$]::text[],
    41.37,
    21.25,
    $sr$Параглајдерско место Крушево$sr$,
    $sr$Krushevo Paragliding Spot$sr$,
    $sr$Највисокиот град во Македонија нуди поглед од воздух за оние што се осмелуваат да ја остават земјата.$sr$,
    $sr$Macedonia's highest town offers aerial perspectives for those who dare to leave the ground behind.$sr$,
    $sr$Крушево седи на 1.350 метри, највисокиот град во Северна Македонија и легенда за параглајдеристите. Патот нагоре сам по себе е цел — серпентини низ пасишта кон град што ги допира облаците. Споменик Илинден го крунисува градот, бруталистички брод во спомен на востанието. Од местата за полетување луѓето едрат на термики над западна Македонија. Дури и ако не се одвоите од земјата, глетката на тие човечки птици ви ја менува перспективата.$sr$,
    $sr$Krushevo sits at 1,350 meters, making it North Macedonia's highest town and a legendary destination for paragliders worldwide. The road up is itself a destination—switchbacks climbing through pastoral landscapes toward a town that seems to touch the clouds. The Ilinden monument crowns the town, a brutalist spaceship commemorating a rebellion that briefly created Europe's first republic. But it's the sky that draws most visitors here. From the launch sites above town, paragliders sail on thermals that rise from sun-warmed valleys, circling above a landscape that encompasses much of western Macedonia. Even if you never leave the ground, watching these human birds find freedom in air currents you can't see reminds you that perspective changes everything.$sr$,
    $sr$Каде што патиштата завршуваат, а крилјата почнуваат$sr$,
    $sr$Where roads end and wings begin$sr$,
    array[$sr$Искачувањето до Крушево ги тестира моторот и возачот — проверете го ладењето$sr$, $sr$Тандем летови има за почетници — резервирајте однапред$sr$, $sr$Илинден нуди панорама без да се одвоите од земјата$sr$]::text[],
    array[$sr$The climb to Krushevo tests engines and riders alike—check your cooling system$sr$, $sr$Tandem paragliding flights available for the uninitiated—book in advance$sr$, $sr$The Ilinden monument offers panoramic views without leaving earth$sr$]::text[],
    $sr$draft$sr$::public.publish_status,
    14,
    $sr$machine$sr$::public.translation_status
  ),
(
    $sr$demir-kapija-gorge$sr$,
    $sr$Central$sr$::public.region,
    array[$sr$Roads$sr$, $sr$Adventure$sr$, $sr$Nature$sr$]::text[],
    41.4,
    22,
    $sr$Вардарска клисура Демир Капија$sr$,
    $sr$Demir Kapija Vardar Gorge$sr$,
    $sr$Железна порта каде што Вардар ја пробил планината, со ѕидови за качување и кајак.$sr$,
    $sr$Iron Gate gorge where the Vardar River carved through mountains, creating limestone walls for rock climbing and kayaking.$sr$,
    $sr$Името значи Железна порта, и кога ќе ги видите вапненичките ѕидови низ кои Вардар си го пробил патот, разбирате зошто. Ова е геологија како драма — вертикални карпи, тунели низ камен, мостови над реката. За авантуристите карпите нудат качување, а реката кајак кога пролетната вода е висока. И од седлото Демир Капија покажува дека планините се виткаат пред водата.$sr$,
    $sr$The name means 'Iron Gate,' and when you see the towering limestone walls through which the Vardar River forced its passage, you understand why. This is geology as drama—vertical cliffs rising hundreds of meters, carved by water's patient insistence over millennia. The road through the gorge ranks among the Balkans' most dramatic rides: tunnels punch through solid rock, bridges span the rushing river, and around every curve, new walls of stone rise to frame the sky. For adventurers, the cliffs offer world-class rock climbing; the river provides challenging kayaking when the spring melt runs high. But even viewed from the saddle, Demir Kapija demonstrates nature's power to reshape the world. Mountains bend to water. Stone yields to persistence. Some doors, once opened, can never close.$sr$,
    $sr$Каде што реките ги кршат планините$sr$,
    $sr$Where rivers break mountains$sr$,
    array[$sr$Патот низ клисурата има малку места за застанување — изберете ги внимателно$sr$, $sr$Винариите на јужниот излез прават одличен вранец$sr$, $sr$Утринската светлина ги бои источните карпи во злато$sr$]::text[],
    array[$sr$The gorge road offers limited stopping points—scout safe pull-offs carefully$sr$, $sr$Local wineries near the southern exit produce excellent Vranec reds$sr$, $sr$Morning light illuminates the eastern cliffs in stunning gold$sr$]::text[],
    $sr$draft$sr$::public.publish_status,
    15,
    $sr$machine$sr$::public.translation_status
  ),
(
    $sr$popova-kula-winery$sr$,
    $sr$Central$sr$::public.region,
    array[$sr$Food Stops$sr$, $sr$Views$sr$, $sr$Cultural$sr$]::text[],
    41.42,
    22.02,
    $sr$Винарија Попова Кула$sr$,
    $sr$Popova Kula Winery$sr$,
    $sr$Ридови под лозја, каде што розето и стариот вранец ја раскажуваат приказната на тероарот.$sr$,
    $sr$Vineyard-draped hills where soulful rosé and ancient Vranec grapes tell stories of sun-soaked terroir.$sr$,
    $sr$Во ридовите кај Демир Капија, каде што долината на Вардар прави микроклима за грозје, Попова Кула го подигнала македонското винарство до уметност. Патот вие низ тераси што светат зелено врз црвената земја. Винаријата ги спојува старите навики со современ поглед, особено со вранец и розе. За возачот ова е друг вид патување: пауза во движењето, место искажано преку вкус, а не преку гас.$sr$,
    $sr$In the hills near Demir Kapija, where the Vardar River valley creates a microclimate perfect for grapes, Popova Kula has elevated Macedonian winemaking to an art form. The road here winds through terraced vineyards that seem to glow green against the region's characteristic red earth. The winery itself combines ancient winemaking traditions with modern vision, producing wines—especially their signature Vranec and rosé—that compete with the world's best. For riders, this represents a different kind of journey: a pause in motion, an appreciation of place expressed through taste rather than throttle. The tasting room overlooks endless vineyard rows, and each sip tells the story of this particular soil, this specific sun, this unique corner of a country that has grown wine for millennia.$sr$,
    $sr$Каде што виното зборува, а возачите слушаат$sr$,
    $sr$Where wine speaks and riders listen$sr$,
    array[$sr$Одредете трезен возач или преноќете близу — вината бараат внимание$sr$, $sr$Дегустација на зајдисонце на терасата оди со локално сирење$sr$, $sr$Имотот понекогаш има берби — проверете го календарот$sr$]::text[],
    array[$sr$Designate a sober rider or book accommodation nearby—the wines demand appreciation$sr$, $sr$Sunset tastings on the terrace pair perfectly with local cheese boards$sr$, $sr$The estate sometimes hosts harvest events—check their calendar$sr$]::text[],
    $sr$draft$sr$::public.publish_status,
    16,
    $sr$machine$sr$::public.translation_status
  ),
(
    $sr$burial-mound-unbeaten$sr$,
    $sr$Central$sr$::public.region,
    array[$sr$Cultural$sr$, $sr$Views$sr$, $sr$Hidden Gem$sr$]::text[],
    41.32,
    21.53,
    $sr$Могила на непобедените$sr$,
    $sr$Burial Mound of the Unbeaten$sr$,
    $sr$Бруталистички споменик над Прилеп, каде што строгата архитектура ја чествува жртвата.$sr$,
    $sr$Brutalist spomenik rising from Prilep's hills, where stark architecture honors partisan sacrifice.$sr$,
    $sr$На рид над Прилеп се издига еден од најдраматичните југословенски споменици. Македониум, познат и како Могила на непобедените, ја памети партизанската борба со архитектура што ги крши очекувањата. Кругови од бетон, прецизни ѕидови и простори што спојуваат триумф и жалост. Патот нагоре минува низ тутун и овоштарници. Внатре акустиката го засилува секој звук; надвор панорамата ја зема целата Прилепска Котлина.$sr$,
    $sr$On a hill overlooking Prilep, one of Yugoslavia's most dramatic spomeniks—memorial monuments—rises like a concrete dream against the Macedonian sky. The Makedonium, also known as the Burial Mound of the Unbeaten, commemorates the partisan resistance with architecture that challenges every expectation. Circles of concrete, walls of geometric precision, and spaces that somehow combine triumph with mourning create an experience unlike any other memorial on Earth. The road up passes through tobacco fields and orchards before reaching this otherworldly structure. Inside, acoustic effects amplify every sound; outside, panoramic views encompass the entire Prilep valley. Whether you appreciate brutalist architecture or simply seek places that defy categorization, this monument commands attention and respect.$sr$,
    $sr$Каде што споменот добива монументален облик$sr$,
    $sr$Where memory takes monumental form$sr$,
    array[$sr$Внатрешната акустика прави чудни одеци — застанете во средината и шепнете$sr$, $sr$Залезот го бои бетонот во топли тонови што денот ги крие$sr$, $sr$Спојте го со Трескавец за цел ден околу Прилеп$sr$]::text[],
    array[$sr$The interior acoustics create eerie echoes—stand in the center and whisper$sr$, $sr$Sunset paints the concrete in warm tones impossible during harsh daylight$sr$, $sr$Combine with Treskavec Monastery for a full day of Prilep-area exploration$sr$]::text[],
    $sr$draft$sr$::public.publish_status,
    17,
    $sr$machine$sr$::public.translation_status
  ),
(
    $sr$markos-towers$sr$,
    $sr$Central$sr$::public.region,
    array[$sr$Fortress$sr$, $sr$Adventure$sr$, $sr$Cultural$sr$]::text[],
    41.35,
    21.56,
    $sr$Маркови Кули$sr$,
    $sr$Marko's Towers$sr$,
    $sr$Остатоци од средновековна тврдина каде што владеел кралот Марко, со пешачење низ историја.$sr$,
    $sr$Medieval fortress remnants where legendary King Marko once ruled, offering epic hiking through history.$sr$,
    $sr$Над Прилеп, драматичните карпи наречени Маркови Кули ги чуваат урнатините на тврдина врзана за една од најголемите балкански легенди. Крале Марко — дел историја, дел мит — јава на Шарец низ народните песни. Тврдината се држи за гранитни игли. Патот ве носи близу, но последното искачување е пеш. Меѓу кулите ветрот носи шепот на битки. Без разлика дали верувате во херои, стоејќи каде што стоел Марко ќе разберете зошто некои ликови ја надживуваат историјата.$sr$,
    $sr$Above Prilep, the dramatic rock formations known as Marko's Towers hold the ruins of a medieval fortress associated with one of the Balkans' most legendary figures. Prince Marko—part historical ruler, part mythological hero—features in folk songs throughout the region as a champion of justice riding his magical horse Šarac. The fortress that bears his name clings to impossible granite spires, demanding a hike that tests legs and rewards souls. The road brings you close, but the final ascent requires feet. Among the towers, wind carries whispers of battles fought and legends born. Views extend to horizons that once marked the boundaries of kingdoms now remembered only in song. Whether you believe in heroes or not, standing where Marko stood, you'll understand why some figures transcend mere history.$sr$,
    $sr$Каде што легендите ги оставиле стапалките$sr$,
    $sr$Where legends left their footprints$sr$,
    array[$sr$Пешачењето до кулите трае 45–60 минути — одвојте време и вода$sr$, $sr$Потребни се цврсти чевли — гранитот не простува лизгање$sr$, $sr$Локалните водичи ги оживуваат камењата со приказни за Марко$sr$]::text[],
    array[$sr$The hike to the towers takes 45-60 minutes—budget time and water accordingly$sr$, $sr$Sturdy footwear is essential—the granite is unforgiving to slips$sr$, $sr$Local guides can share Marko legends that bring the stones to life$sr$]::text[],
    $sr$draft$sr$::public.publish_status,
    18,
    $sr$machine$sr$::public.translation_status
  ),
(
    $sr$carevi-kuli$sr$,
    $sr$East$sr$::public.region,
    array[$sr$Fortress$sr$, $sr$Views$sr$, $sr$Cultural$sr$]::text[],
    41.4412,
    22.6521,
    $sr$Тврдина Цареви Кули$sr$,
    $sr$Carevi Kuli Fortress$sr$,
    $sr$Урнатини на рид од каде што византиските цареви ја гледале долината, а денес глетката е за душата.$sr$,
    $sr$Hilltop ruins where Byzantine emperors once surveyed their domain, now offering panoramic soul views over the valley.$sr$,
    $sr$Високо над Струмица, древните ѕидови на Цареви Кули стојат како тивки сведоци на илјада години. Оваа византиска тврдина некогаш командувала со погледи што правеле империи. Денес истите погледи командуваат со стравопочит и тишина. Патот се вие низ дабови шуми и овоштарници, и секоја фиока открива повеќе од Струмичката Котлина. На врвот урнатите ѕидови го рамнат небото. Камењата паметат. Сега ќе паметите и вие.$sr$,
    $sr$High above Strumica, the ancient walls of Carevi Kuli—the Tsar's Towers—stand as silent witnesses to a thousand years of history. This Byzantine fortress, perched on a dramatic hilltop, once commanded views that made empires possible. Today, the same views command something different: awe, silence, and the peculiar peace that comes from standing where history happened. The road winds upward through oak forests and past orchards heavy with fruit, each switchback revealing more of the Strumica valley below. At the summit, ruined walls frame the sky like ancient picture frames, and the wind carries whispers of battles fought, lovers met, and prayers offered. This isn't mere archaeology—it's a conversation across centuries. The stones remember. And now, so will you.$sr$,
    $sr$Каде што царевите сонувале во камен$sr$,
    $sr$Where emperors dreamed in stone$sr$,
    array[$sr$Златниот час ги претвора урнатините во килибар — времејте го пристигнувањето$sr$, $sr$Последниот приод ги наградува способните гуми и мирната рачка на гас$sr$, $sr$Понесете локална ракија — залезот заслужува наздравица$sr$]::text[],
    array[$sr$Golden hour transforms the ruins into amber-lit poetry—time your arrival$sr$, $sr$The final approach rewards capable tires and steady throttle control$sr$, $sr$Pack a flask of local rakija—the sunset deserves a toast$sr$]::text[],
    $sr$draft$sr$::public.publish_status,
    19,
    $sr$machine$sr$::public.translation_status
  ),
(
    $sr$vodoca-monastery$sr$,
    $sr$East$sr$::public.region,
    array[$sr$Cultural$sr$, $sr$Hidden Gem$sr$]::text[],
    41.4506,
    22.5903,
    $sr$Водочки манастир$sr$,
    $sr$Vodoča Monastery$sr$,
    $sr$Црквата на Свети Леонтиј во селото Водоча, кратко возење западно од Струмица.$sr$,
    $sr$Saint Leontius's church in the village of Vodoča, a short ride west of Strumica.$sr$,
    $sr$На околу пет километри од Струмица, селото Водоча го чува манастирот на Свети Леонтиј. Црквата во која влегувате не е една градба, туку три споени низ вековите: ранохристијанска базилика од V и VI век, подоцнежна куполна црква, и сегашната обновена по земјотресот во 1931. Патот од Струмица е краток. Дворот не е. Ако седите доволно долго, водопадите на источната јамка ви звучат како гласната половина од истиот ден. Координатите се за проверка пред објава.$sr$,
    $sr$About five kilometers from Strumica, the village of Vodoča keeps the monastery of Saint Leontius. The church you walk into is not one building but three, joined over centuries: an early Christian basilica stood here in the 5th and 6th centuries, a domed church rose later, and the present church was rebuilt after the 1931 earthquake. The road out from Strumica is short. The courtyard is not. Sit long enough and the eastern loop's waterfalls feel like the loud half of the same day.$sr$,
    $sr$Каде што три цркви делат една тишина$sr$,
    $sr$Where three churches share one silence$sr$,
    array[$sr$Од Струмица е неколку минути, па спојте го со Колешино и Смоларе$sr$, $sr$Црквата бара скромна облека — покријте ги рамената пред да влезете$sr$, $sr$Земјотресот од 1931 го зел стариот ентериер; тишината во дворот е она што останало$sr$]::text[],
    array[$sr$It is a few minutes from Strumica, so pair it with Kolesino and Smolare rather than a separate day$sr$, $sr$The church asks for modest dress — cover shoulders before you step inside$sr$, $sr$The 1931 earthquake took the old interior; the silence in the courtyard is what remains$sr$]::text[],
    $sr$draft$sr$::public.publish_status,
    20,
    $sr$machine$sr$::public.translation_status
  ),
(
    $sr$kolesino-waterfall$sr$,
    $sr$East$sr$::public.region,
    array[$sr$Waterfalls$sr$, $sr$Nature$sr$, $sr$Hidden Gem$sr$]::text[],
    41.3575,
    22.8067,
    $sr$Колешински Водопад$sr$,
    $sr$Kolesino Waterfall$sr$,
    $sr$Води паѓаат низ бујните ридови на Беласица, освежување за уморни души.$sr$,
    $sr$Cascading waters tumble through lush Belasica hills, offering the perfect refreshing stop for weary souls.$sr$,
    $sr$Скриен во шумските набори на Беласица, Колешинскиот Водопад паѓа 15 метри во базен како направен за тишина. Патот вие низ костенови шуми и покрај камени куќи каде што времето оди со реката. Кратка патека води од паркингот, и секој чекор го придружува сè посилното татнење. На видиковецот маглата ги освежува возачите. Пролетта го набабрува текот; есента го рамни белиот млаз со златни лисја. Колешино учи дека најсилните места понекогаш се најинтимните.$sr$,
    $sr$Hidden in the forested folds of Belasica Mountain, Kolesino Waterfall plunges 15 meters into a pool that seems designed for contemplation. The road winds through chestnut forests and past traditional stone houses where time moves at the pace of the river. A short trail leads from the parking area to the falls, each step accompanied by the growing thunder of falling water. At the viewpoint, mist refreshes riders weary from mountain roads, and the cascade itself creates a natural amphitheater of sound. In spring, snowmelt swells the flow to thundering power; in autumn, golden leaves frame the white rush. This isn't a destination for those who measure worth in scale—Kolesino teaches that sometimes the most powerful places are the most intimate.$sr$,
    $sr$Каде што водата му пее на каменот$sr$,
    $sr$Where water sings to stone$sr$,
    array[$sr$Кратката патека е стрмна, но поплочена — глетката го плаќа секој чекор$sr$, $sr$Пролетниот надој е најдраматичен; летото е полесно за капење$sr$, $sr$Спојте го со Смоларскиот Водопад за ден со два слапа$sr$]::text[],
    array[$sr$The short trail is steep but paved—the view rewards every step$sr$, $sr$Spring runoff creates the most dramatic falls—summer offers easier swimming$sr$, $sr$Combine with Smolare Waterfall for a double cascade day$sr$]::text[],
    $sr$draft$sr$::public.publish_status,
    21,
    $sr$machine$sr$::public.translation_status
  ),
(
    $sr$smolare-waterfall$sr$,
    $sr$East$sr$::public.region,
    array[$sr$Waterfalls$sr$, $sr$Adventure$sr$, $sr$Nature$sr$]::text[],
    41.3456,
    22.8789,
    $sr$Смоларски Водопад$sr$,
    $sr$Smolare Waterfall$sr$,
    $sr$Највисокиот водопад во Македонија татни низ чиста шума, споменик на вертикалата.$sr$,
    $sr$Macedonia's tallest waterfall thunders through pristine forest, a monument to nature's vertical ambitions.$sr$,
    $sr$Со 39 метри Смоларе го носи називот највисок водопад во Северна Македонија, но бројката не ја фаќа душата. Скриен во шумите на Беласица, достапен само за оние што ќе ги остават главните патишта, тој ја награди посветеноста со спектакл. Патеката се качува низ букова шума додека целата висина на водата не го наполни погледот. Звукот расте и ја дави мислата. На вистински агол прскањето прави виножита. Ова е најдраматичниот единечен пад во земјата, скриен во ридови што повеќето патници никогаш не ги истражуваат.$sr$,
    $sr$At 39 meters, Smolare claims the title of North Macedonia's tallest waterfall—but statistics fail to capture its soul. Hidden in the forests of Belasica, accessible only to those willing to leave the main roads behind, Smolare rewards commitment with spectacle. The trail climbs through beech forest, each switchback revealing glimpses of the cascade ahead, until the full height of falling water fills your vision. The sound builds as you approach—a white noise of nature that drowns thought and invites presence. At the viewpoint, spray creates rainbows when the angle is right, and the sheer verticality of the falls reminds you that gravity itself is an art form. This is Macedonia's most dramatic single drop, hidden in hills that most travelers never explore. Their loss. Your gain.$sr$,
    $sr$Каде што височините се предаваат на падот$sr$,
    $sr$Where the heights surrender to the fall$sr$,
    array[$sr$Дваесетминутното пешачење вреди — водопадот сака да се види одблизу$sr$, $sr$Раните утра носат самотија; викендите носат семејства$sr$, $sr$Пристапниот пат е тесен — помалите мотори имаат предност$sr$]::text[],
    array[$sr$The 20-minute hike is worth every step—the falls demand to be seen up close$sr$, $sr$Early morning visits offer solitude; weekends bring families$sr$, $sr$The access road is narrow—smaller bikes have the advantage$sr$]::text[],
    $sr$draft$sr$::public.publish_status,
    22,
    $sr$machine$sr$::public.translation_status
  ),
(
    $sr$berovo-lake$sr$,
    $sr$East$sr$::public.region,
    array[$sr$Nature$sr$, $sr$Views$sr$, $sr$Hidden Gem$sr$]::text[],
    41.71,
    22.88,
    $sr$Беровско Езеро$sr$,
    $sr$Berovo Lake$sr$,
    $sr$Алпски мир во Малешевијата, каде што боровите го гушкаат планинското бегство.$sr$,
    $sr$Alpine serenity in the Maleshevo highlands, where pine forests embrace a perfect mountain escape.$sr$,
    $sr$На крајниот исток, каде што Малешевските Планини се приближуваат до бугарската граница, Беровското Езеро нуди друг вид бегство. Оваа акумулација остарела во природна убавина — борови по брегот, кругови од риби, врвови како зелен амфитеатар. Патот минува низ едни од најмалку посетените предели, низ села каде што старата архитектура останала затоа што никогаш не се расипала. На езерото патеките се разидуваат во дивината, но многумина само седат на брегот. Ова е тивкиот агол на Македонија, каде што единствената итност е залезот.$sr$,
    $sr$In the far east of Macedonia, where the Maleshevo Mountains approach the Bulgarian border, Berovo Lake offers a different kind of escape. This artificial reservoir has aged into natural beauty—pine forests crowd its shores, fish circles disturb its surface, and the surrounding peaks create a natural amphitheater of green. The road here passes through some of Macedonia's least-visited landscapes, climbing through villages where traditional architecture remains unrestored because it never fell into disrepair. At the lake, hiking trails radiate into the surrounding wilderness, but many visitors simply find a spot on the shore and let the highland air work its restorative magic. This is Macedonia's quiet corner, where the pace slows naturally and the only urgency is sunset.$sr$,
    $sr$Каде што висорамнините го задржуваат здивот$sr$,
    $sr$Where the highlands hold their breath$sr$,
    array[$sr$Беровското бело сирење е легендарно — купете за патот$sr$, $sr$Шумските патеки даваат сенка во жешките денови$sr$, $sr$Есента ги бои шумите во злато и црвено$sr$]::text[],
    array[$sr$The white cheese of Berovo is legendary—buy some for the journey$sr$, $sr$Forest trails offer shade on hot days—perfect for midday escapes$sr$, $sr$Autumn paints the surrounding forests in spectacular gold and crimson$sr$]::text[],
    $sr$draft$sr$::public.publish_status,
    23,
    $sr$machine$sr$::public.translation_status
  ),
(
    $sr$belasica-mountain-summit$sr$,
    $sr$East$sr$::public.region,
    array[$sr$Mountain$sr$, $sr$Adventure$sr$, $sr$Views$sr$]::text[],
    41.3125,
    22.7456,
    $sr$Врв на Беласица$sr$,
    $sr$Belasica Mountain Summit$sr$,
    $sr$Граничен срт меѓу светови, каде што Македонија се среќава со Грција и Бугарија.$sr$,
    $sr$Border ridge between worlds, where Macedonia meets Greece and Bulgaria in alpine drama.$sr$,
    $sr$Беласица се издига како ѕид меѓу народите — сртот означува каде завршува Северна Македонија и почнуваат Грција и Бугарија. На овие височини границите изгледаат неважни. Планината зборува јазик постар од државите: ветер низ алпски ливади, јастреби на термики, снег што трае до јули. Патот се качува низ најпространите костенови шуми во Европа, па низ бука, па до отворена трева каде што останува само небо. Од горните падини се гледаат три држави. Малку возачи стигнуваат толку далеку на исток. Беласица вреди аџилак.$sr$,
    $sr$Belasica rises as a wall between nations—its summit ridge marking where North Macedonia ends and Greece and Bulgaria begin. But at these altitudes, borders seem irrelevant. The mountain speaks a language older than nations: wind through alpine meadows, hawks circling on thermals, snow patches that linger until July. The road climbs through chestnut forests—Europe's most extensive—before giving way to beech and finally to open grassland where only sky remains above. The views from the upper slopes encompass three countries, two valleys, and a horizon so vast it curves with the Earth itself. Few riders venture this far east, which means you'll likely have the mountain largely to yourself. Some roads are worth the journey. Belasica is worth the pilgrimage.$sr$,
    $sr$Каде што три земји го среќаваат небото$sr$,
    $sr$Where three lands meet the sky$sr$,
    array[$sr$Утринските искачувања носат посвеж воздух$sr$, $sr$Над шумската граница патот се стеснува — внимавајте на овчари и стада$sr$, $sr$Носете слоеви: врвот може да биде 10 степени постуден од долината$sr$]::text[],
    array[$sr$Morning ascents offer cooler temperatures and cleaner mountain air$sr$, $sr$The road narrows above treeline—ride alert for oncoming shepherds and their flocks$sr$, $sr$Pack layers: the summit can be 10°C cooler than the valley floor$sr$]::text[],
    $sr$draft$sr$::public.publish_status,
    24,
    $sr$machine$sr$::public.translation_status
  ),
(
    $sr$pelister-national-park$sr$,
    $sr$West$sr$::public.region,
    array[$sr$Mountain$sr$, $sr$Nature$sr$, $sr$Adventure$sr$]::text[],
    41.02,
    21.2,
    $sr$Национален парк Пелистер$sr$,
    $sr$Pelister National Park$sr$,
    $sr$Древните патеки на Баба Планина вијат низ моликови шуми кон леднички езера.$sr$,
    $sr$Baba Mountain's ancient trails wind through endemic Molika pine forests toward glacial lakes and endless vistas.$sr$,
    $sr$Првиот национален парк во Македонија чува нешто незаменливо: моликата, вид што тука расте — и речиси никаде на друго место — пет милиони години. Возењето во Пелистер личи на влегување во катедрала од живи фосили. Патот рамномерно се качува низ шуми постари од државите. Повисоко, двете леднички езера наречени Очи на Пелистер одразуваат небо толку сино што изгледа насликано. Паркот има патеки за оние што ќе ги остават тркалата. Но и самиот пат наградува: секој метар висина носи нов поглед.$sr$,
    $sr$Macedonia's first national park protects something irreplaceable: the Molika pine, a species that has grown here—and almost nowhere else—for five million years. Riding into Pelister feels like entering a cathedral of living fossils. The road climbs steadily, switching back through forests that predate not just nations but epochs. At higher elevations, the famous 'Eyes of Pelister'—two glacial lakes—reflect skies so blue they seem painted. The park offers trails for those willing to leave wheels behind and continue on foot, leading to peaks where the entire region spreads below like a topographic dream. But even the road itself rewards: each meter of elevation brings new views, new silences, and new appreciation for a landscape that has waited five million years for you to notice.$sr$,
    $sr$Каде што пет милиони години трпение цветаат$sr$,
    $sr$Where five million years of patience bloom$sr$,
    array[$sr$Ледничките езера бараат пешачење од патот — планирајте 2–3 часа во двата правци$sr$, $sr$Во паркот има планински колиби за ноќевање$sr$, $sr$Есента ги претвора шумите во килибар и злато$sr$]::text[],
    array[$sr$The glacial lakes require a hike from the road—plan 2-3 hours round trip$sr$, $sr$Park facilities include mountain huts for overnight adventures$sr$, $sr$Autumn transforms the forests into amber and gold spectacle$sr$]::text[],
    $sr$draft$sr$::public.publish_status,
    25,
    $sr$machine$sr$::public.translation_status
  ),
(
    $sr$kozjak-canyon$sr$,
    $sr$Central$sr$::public.region,
    array[$sr$Nature$sr$, $sr$Adventure$sr$, $sr$Hidden Gem$sr$]::text[],
    41.99,
    21.25,
    $sr$Кањон Козјак$sr$,
    $sr$Kozjak Canyon$sr$,
    $sr$Груб крај на акумулација каде што вапненички карпи ја гушкаат тиркизната вода.$sr$,
    $sr$Rugged reservoir country where limestone cliffs embrace turquoise waters in dramatic geological embrace.$sr$,
    $sr$Подалеку од попознатата Матка лежи Козјак — нејзиниот потивок и потаинствен брат. Овој кањон, издлабен од води сега скротени во езера, нуди едни од најдраматичните предели на централна Македонија без толпата. Патот ја следи водата низ сè потесни процепи, додека небото не стане лента над глава. Летни базени канат на пауза, а каменот ја голта бучавата. Козјак ги наградува оние што продолжуваат таму каде што повеќето се враќаат.$sr$,
    $sr$Beyond the more famous Matka lies Kozjak—its quieter, more mysterious sibling. This canyon system, carved by waters now tamed into reservoirs, offers some of central Macedonia's most dramatic landscapes without the crowds. The road follows the water through increasingly tight passages, cliffs rising on both sides until the sky becomes a ribbon overhead. Swimming holes invite summer pauses; climbing routes challenge the vertical-minded; and everywhere, the peculiar silence of canyon country—sounds absorbed by stone, echoes returning unexpected—creates an atmosphere of profound solitude. Kozjak rewards those willing to venture beyond the obvious, to follow roads less marked, to discover that sometimes the greatest beauty hides just past the point where most travelers turn back.$sr$,
    $sr$Каде што кањоните чуваат тајни$sr$,
    $sr$Where canyons keep secrets$sr$,
    array[$sr$Патот на места е груб — препорачани се гуми за авантура$sr$, $sr$Понесете костим во лето — скриените базени ги чекаат подготвените$sr$, $sr$Почитувајте ги ознаките за приватно земјиште — некаде треба дозвола$sr$]::text[],
    array[$sr$The canyon road can be rough in sections—adventure-ready tires recommended$sr$, $sr$Bring swimming gear in summer—hidden pools await the prepared$sr$, $sr$Respect private land markers—some access requires local permission$sr$]::text[],
    $sr$draft$sr$::public.publish_status,
    26,
    $sr$machine$sr$::public.translation_status
  ),
(
    $sr$vodno-mountain-cross$sr$,
    $sr$Central$sr$::public.region,
    array[$sr$Viewpoints$sr$, $sr$Views$sr$, $sr$Mountain$sr$]::text[],
    41.96,
    21.35,
    $sr$Крст на Водно$sr$,
    $sr$Vodno Mountain Cross Summit$sr$,
    $sr$Висок крст со панорама од 360 степени, каде што Скопје го среќава небото.$sr$,
    $sr$High cross monument with 360° city-mountain panoramas where Skopje meets the sky.$sr$,
    $sr$Милениумскиот Крст се издига 66 метри над врвот на Водно и се гледа од цело Скопје. Вистинското откровение доаѓа горе: главниот град што изгледал огромен станува играчка во долината, а планините околу него се бескраен амфитеатар. Во ведар ден хоризонтот стигнува кон Грција, Косово и Србија. Патот нагоре се префрла низ даб и бука додека крстот не се појави над вас. Ноќе свети килибарно. Ова е најдостапниот висок видиковец во Македонија, и токму затоа пристигнувањето е магично.$sr$,
    $sr$Rising 66 meters above Vodno's summit, the Millennium Cross is visible from across Skopje—a beacon that seems to invite the city skyward. But the true revelation comes when you reach the top: suddenly, the capital that seemed so vast becomes a toy city spread across the valley floor, and the mountains that ring it reveal themselves as an infinite amphitheater of peaks. On clear days, you can trace horizons that span into Greece, Kosovo, and Serbia. The ride up switches through oak and beech forests, gaining altitude with every curve until the cross appears above, shimmering in whatever light the day offers. At night, it glows amber, a warm signal visible from the roads below. This is Macedonia's most accessible high viewpoint—and somehow, that accessibility only heightens the magic of arrival.$sr$,
    $sr$Каде што градот долу станува шепот$sr$,
    $sr$Where the city becomes a whisper below$sr$,
    array[$sr$Патот се затвора за возила во прометни денови — проверете пред да тргнете$sr$, $sr$Изгрејсонцето значи да го гледате градот како се буди под вас$sr$, $sr$Жичницата е алтернатива — вистинските возачи го бираат вијугавиот пат$sr$]::text[],
    array[$sr$The road closes to vehicles on busy days—check conditions before riding$sr$, $sr$Sunrise here means watching the city wake while you float above$sr$, $sr$The cable car is an alternative—but real riders take the winding road$sr$]::text[],
    $sr$draft$sr$::public.publish_status,
    27,
    $sr$machine$sr$::public.translation_status
  ),
(
    $sr$st-jovan-kaneo-overlook$sr$,
    $sr$West$sr$::public.region,
    array[$sr$Viewpoints$sr$, $sr$Views$sr$, $sr$Cultural$sr$]::text[],
    41.11,
    20.78,
    $sr$Видиковец Св. Јован Канео$sr$,
    $sr$St Jovan Kaneo Overlook$sr$,
    $sr$Црква на карпа каде што древниот камен ја среќава бескрајната сина вода на Охрид.$sr$,
    $sr$Cliffside church vista where ancient stone meets endless blue waters of Lake Ohrid.$sr$,
    $sr$Некои цркви се градени да ги засолнат верниците; Свети Јован Канео е граден да ги натера да летаат. Качена на карпа директно над бистрата вода на Охридското Езеро, оваа црква од XIII век е можеби најфотографираната градба во Северна Македонија. Од видиковецот езерото се протега до албанските планини, стариот град се спушта кон брегот, а црквата како да лебди меѓу небото и длабочината. Во златниот час каменот се стоплува, а езерото станува течно злато.$sr$,
    $sr$Some churches were built to shelter worshippers; St. Jovan Kaneo was built to make them fly. Perched on a cliff directly above Lake Ohrid's crystalline waters, this 13th-century church is perhaps the most photographed building in all of North Macedonia—and from the overlook above, you understand why. The lake stretches to Albania's mountains, the old town cascades down to the shore, and the church itself seems to defy gravity, suspended between heaven and the deep. The path to the overlook winds through terraced gardens and ancient walls, revealing new angles with each step. At golden hour, the stone glows warm, the lake turns to liquid gold, and time dissolves into something eternal. This isn't just a viewpoint; it's a meditation on what humans can create when they build with reverence.$sr$,
    $sr$Каде што молитвите лебдат на вода илјада години$sr$,
    $sr$Where prayers have floated on water for a thousand years$sr$,
    array[$sr$Паркирајте во стариот град и последниот дел пешачете — патеката ги наградува трпеливите$sr$, $sr$Зората е волшебна — победете ја и толпата и жештината$sr$, $sr$Почитувајте ја активната црква — фотографијата е добредојдена, тишината уште повеќе$sr$]::text[],
    array[$sr$Park at the old town and walk the final approach—the path rewards the patient$sr$, $sr$Dawn light here is magical—beat the crowds and the heat together$sr$, $sr$Respect the active church—photography is welcome, silence more so$sr$]::text[],
    $sr$draft$sr$::public.publish_status,
    28,
    $sr$machine$sr$::public.translation_status
  ),
(
    $sr$kokino-observatory-overlook$sr$,
    $sr$East$sr$::public.region,
    array[$sr$Viewpoints$sr$, $sr$Views$sr$, $sr$Cultural$sr$, $sr$Hidden Gem$sr$]::text[],
    42.26,
    21.95,
    $sr$Видиковец Кокино$sr$,
    $sr$Kokino Observatory Overlook$sr$,
    $sr$Древна мегалитска опсерваторија со ѕвездено небо и порамнувања стари 4.000 години.$sr$,
    $sr$Ancient hilltop megalith site with starry vistas and 4000-year-old astronomical alignments.$sr$,
    $sr$Пред четири илјади години астрономи од бронзеното доба стоеле на оваа карпа и го следеле небото. Денес Кокино е меѓу најважните древни опсерватории на светот. Пределот паѓа на сите страни и прави природен амфитеатар со небото за таван. Карпите ги означуваат солстициумите и рамнодениците со прецизност што современите инструменти едвај ја подобруваат. Дојдете во зори да го видите сонцето низ древните белези. Дојдете во кој било час за да ја почувствувате врската меѓу човечката љубопитност и космосот.$sr$,
    $sr$Four thousand years ago, Bronze Age astronomers stood on this rocky outcrop and tracked the heavens. Today, Kokino ranks among the world's most important ancient observatories—and from its summit, you understand why our ancestors chose this place. The landscape falls away in every direction, creating a natural amphitheater with the sky as its ceiling. Rock formations mark solstices and equinoxes with precision that modern instruments can barely improve. Come at dawn to watch the sun rise through ancient markers. Come at dusk to see stars emerge exactly where they emerged for Neolithic priests. Come at any hour to feel the profound connection between human curiosity and cosmic mystery. This is not just a viewpoint—it's a portal to humanity's first wonder at the universe above.$sr$,
    $sr$Каде што древните очи првпат ги мапирале ѕвездите$sr$,
    $sr$Where ancient eyes first mapped the stars$sr$,
    array[$sr$Ноќите без месечина се најдобри за ѕвезди — планирајте според лунарниот циклус$sr$, $sr$Последниот километар е немакадам — бавно и стабилно стигнува$sr$, $sr$Понесете ќебе — да лежите и да ја видите целата купола е задолжително$sr$]::text[],
    array[$sr$New moon nights offer the best stargazing—plan around lunar cycles$sr$, $sr$The final kilometer is unpaved—slow and steady rewards with arrival$sr$, $sr$Bring a blanket—lying back to see the full sky dome is mandatory$sr$]::text[],
    $sr$draft$sr$::public.publish_status,
    29,
    $sr$machine$sr$::public.translation_status
  ),
(
    $sr$galicica-national-park-summit$sr$,
    $sr$West$sr$::public.region,
    array[$sr$Viewpoints$sr$, $sr$Views$sr$, $sr$Mountain$sr$, $sr$Nature$sr$]::text[],
    40.96,
    20.83,
    $sr$Врв на Национален парк Галичица$sr$,
    $sr$Galicica National Park Summit$sr$,
    $sr$Висок алпски видиковец каде што Охрид и Преспа треперат на спротивни хоризонти.$sr$,
    $sr$High alpine viewpoint where two lakes—Ohrid and Prespa—shimmer on opposite horizons.$sr$,
    $sr$Врвот на Галичица нуди нешто што малку места на Земјата можат: истовремен поглед на две езера достојни за УНЕСКО, разделени со сртот што штотуку сте го совладале. Охрид трепери на запад, длабок и стар; Преспа се простира на исток, дива и таинствена. Меѓу нив стоите на 2.265 метри и дишете воздух толку тенок што личи на позајмен од друго време. Патот до врвот ги тестира сите вештини — фиоки, чакал, висина — но наградата го менува значењето на зборот видиковец.$sr$,
    $sr$The summit of Galicica National Park offers what few places on Earth can: simultaneous views of two UNESCO-worthy lakes, separated by a mountain spine you've just conquered. Lake Ohrid glimmers to the west, ancient and deep; Lake Prespa spreads to the east, wild and mysterious. Between them, you stand at 2,265 meters, breathing air so thin and pure it feels borrowed from another era. The alpine meadows here bloom with rare flowers in late spring; the limestone formations create natural sculptures that seem designed for contemplation. The road to reach this summit tests every skill—hairpins, gravel, altitude—but the reward redefines what viewpoints can be. This is not looking at the world; this is standing above it, between two mirrors reflecting the infinite sky.$sr$,
    $sr$Каде што стоите меѓу два древни света$sr$,
    $sr$Where you stand between two ancient worlds$sr$,
    array[$sr$Патот преку превојот е отворен само летос — снегот го затвора од октомври до мај$sr$, $sr$Понесете пикник — ливадите на врвот се за гледање хоризонт$sr$, $sr$Утринската магла ги прави двете езера неземски — наместете будилник$sr$]::text[],
    array[$sr$The pass road opens only in summer—snow closes it from October to May$sr$, $sr$Pack a picnic—the summit meadows are perfect for horizon-watching$sr$, $sr$Early morning mist makes both lakes ethereal—set an alarm for magic$sr$]::text[],
    $sr$draft$sr$::public.publish_status,
    30,
    $sr$machine$sr$::public.translation_status
  ),
(
    $sr$dojran-lake$sr$,
    $sr$East$sr$::public.region,
    array[$sr$Nature$sr$, $sr$Hidden Gem$sr$, $sr$Views$sr$]::text[],
    41.18,
    22.72,
    $sr$Дојранско Езеро$sr$,
    $sr$Dojran Lake$sr$,
    $sr$Мирно погранично езеро каде што трските шепотат, а пеликаните цртаат кругови во магла.$sr$,
    $sr$A tranquil border lake where reed beds whisper secrets and pelicans trace circles in morning mist.$sr$,
    $sr$Префрлено преку грчката граница како тајна меѓу два народа, Дојранското Езеро носи особен мир што го имаат само местата на праг. Некогаш славно по риболовот со корморани, езерото за малку изумре во деведесеттите кога одземањата на вода му го зедоа нивото. Дојран се врати, полека, и екосистемот се сеќава. Денес трските кријат чапји и пеликани, шеталиштето кани на бавен од, а топлите извори велат за лек. На работ на водата, со Грција на спротивниот брег, се разбира дека некои граници се само линии на карта.$sr$,
    $sr$Straddling the Greek border like a secret shared between nations, Dojran Lake embodies a peculiar peace that only threshold places possess. Once famous for its cormorant-guided fishing—a tradition stretching back millennia—the lake nearly died in the 1990s when upstream diversions stole its waters. Yet Dojran returned, slowly refilling, its ecosystem reviving with the patient persistence of nature's memory. Today, reed beds shelter herons and pelicans, the shoreline promenades invite meditative walks, and the thermal waters of nearby springs promise healing. The ride here crosses fertile plains where peppers dry in crimson waves, through villages where time moves at the pace of conversation. At the water's edge, with Greece visible on the opposite shore, you understand that some borders are merely lines on maps. The lake ignores them. So does the soul.$sr$,
    $sr$Шепоти на заборавени граници$sr$,
    $sr$Whispers of forgotten borders$sr$,
    array[$sr$Рибните ресторани на шеталиштето ја служат уловот на скара — чисто и свежо$sr$, $sr$Пролетта носи преселни птици во голем број — двогледот помага$sr$, $sr$Грчката страна дава друг агол — со пасош може ден на две езера$sr$]::text[],
    array[$sr$The fish restaurants on the promenade serve the day's catch simply grilled—pure and fresh$sr$, $sr$Spring brings migratory birds in spectacular numbers—binoculars enhance the experience$sr$, $sr$The Greek side offers different perspectives—passports permit a two-lake day$sr$]::text[],
    $sr$draft$sr$::public.publish_status,
    31,
    $sr$machine$sr$::public.translation_status
  ),
(
    $sr$stobi-ancient-city$sr$,
    $sr$Central$sr$::public.region,
    array[$sr$Cultural$sr$, $sr$Hidden Gem$sr$, $sr$Views$sr$]::text[],
    41.55,
    21.97,
    $sr$Антички град Стоби$sr$,
    $sr$Stobi Ancient City$sr$,
    $sr$Римско-византиски урнатини каде што мозаиците сè уште светат со боите на распаднати империи.$sr$,
    $sr$Roman-Byzantine ruins where mosaics still shimmer with the colors of empires long dissolved into dust.$sr$,
    $sr$На вливот на Црна во Вардар, каде што се крстосувале патишта и култури, Стоби пораснал под Рим и цветал низ византиските векови. Денес, шетајќи по ископаните улици, минувате низ сенката на град што некогаш држел 30.000 души. Мозаици излегуваат од земјата — елени, пауни, геометрија — со бои што преживеале петнаесет века закопани. Театарот сè уште држи ехо, крстилницата го одразува небото. Патот до Стоби ја сече Тиквешијата. Застанете пред зајдисонце и гледајте ја светлината по камен што гледал империи како се раѓаат и умираат.$sr$,
    $sr$At the confluence of the Crna and Vardar rivers, where ancient trade routes crossed and cultures collided, Stobi rose to prominence under Roman rule and flourished through Byzantine centuries. Today, walking its excavated streets, you traverse the ghost of a city that once held 30,000 souls. Mosaics emerge from the earth—deer, peacocks, geometric patterns—their colors somehow surviving fifteen centuries of burial. The theater's stone seats still hold echoes of performances; the baptistry's pool still reflects the sky; the palace foundations still trace the ambitions of governors and bishops. The road to Stobi crosses the Tikveš wine region, where vineyards carpet hills in orderly green rows. Stop here before sunset. Watch the light move across stone that has watched empires rise and fall. Remember that even cities die, but beauty—like these mosaics—sometimes outlasts everything.$sr$,
    $sr$Урнатини што одекнуваат вечни приказни$sr$,
    $sr$Ruins echoing eternal stories$sr$,
    array[$sr$Утринската светлина најдобро ги осветлува мозаиците — дојдете на отворање$sr$, $sr$Спојте го со дегустација во Тиквеш за ден историја и лозје$sr$, $sr$Музејот на лице место им дава контекст на урнатините$sr$]::text[],
    array[$sr$Morning light illuminates the mosaics best—arrive when the site opens$sr$, $sr$Combine with Tikveš wine tasting for a day of history and viticulture$sr$, $sr$The on-site museum provides context that enriches every ruin's meaning$sr$]::text[],
    $sr$draft$sr$::public.publish_status,
    32,
    $sr$machine$sr$::public.translation_status
  ),
(
    $sr$shar-mountain-range$sr$,
    $sr$West$sr$::public.region,
    array[$sr$Mountain$sr$, $sr$Adventure$sr$, $sr$Nature$sr$]::text[],
    42,
    20.8,
    $sr$Шар Планина$sr$,
    $sr$Šar Mountain Range$sr$,
    $sr$Груба алпска дивина каде што леднички езера ги огледуваат врвовите, а овчарите одат по постари патеки од границите.$sr$,
    $sr$Rugged alpine wilderness where glacial lakes mirror peaks and shepherds follow paths older than borders.$sr$,
    $sr$Шар Планина се издига како ѕид меѓу Македонија и Косово, со врвови над 2.700 метри и воздух што има вкус на мраз и диви билки. Ова е една од последните вистински дивини во Европа — мечки во шумите, волци на ливадите, шарпланинци што ги чуваат стадата. Патот се качува од Тетово: овоштарници, па шума, па алпски ливади, па гол камен под вечен снег. На највисоките достапни точки ледничките езера — Очите на планината — одразуваат невозможно сино небо. Овчарите сè уште летуваат во бачила. Секоја фиока е заработена.$sr$,
    $sr$The Šar Mountains rise like a wall between Macedonia and Kosovo, their peaks reaching above 2,700 meters into air so pure it tastes of ice and wild herbs. This is one of Europe's last true wildernesses—brown bears roam the forests, wolves hunt in the high meadows, and the Šarplaninec shepherd dogs guard flocks with ancestry stretching back millennia. The road climbs from the valley town of Tetovo through increasingly dramatic landscapes: orchards give way to forests, forests to alpine meadows, meadows to bare rock crowned with eternal snow. At the highest accessible points, glacial lakes—the 'Eyes of the Mountain'—reflect skies of impossible blue. Nomadic herders still spend summers in mountain huts called 'bačila,' making cheese and maintaining traditions that modernity forgot to erase. This is riding as pilgrimage: every switchback earned, every vista a reward, every breath a reminder that some wild places still exist.$sr$,
    $sr$Врвови што го допираат божественото$sr$,
    $sr$Peaks touching the divine$sr$,
    array[$sr$Попова Шапка летос отвора пристап до највисоките асфалти$sr$, $sr$Сирењето од планинските овчари е течно злато — купете кога ви нудат$sr$, $sr$Времето може од сонце да стане виулица за минути — облечете се во слоеви$sr$]::text[],
    array[$sr$The Popova Šapka ski resort offers summer access to the highest paved roads$sr$, $sr$Local cheese from mountain shepherds is liquid gold—buy when offered$sr$, $sr$Weather can shift from sunshine to blizzard in minutes—layer accordingly$sr$]::text[],
    $sr$draft$sr$::public.publish_status,
    33,
    $sr$machine$sr$::public.translation_status
  ),
(
    $sr$kratovo-old-town$sr$,
    $sr$East$sr$::public.region,
    array[$sr$Cultural$sr$, $sr$Hidden Gem$sr$, $sr$Adventure$sr$]::text[],
    42.02,
    22.18,
    $sr$Стар град Кратово$sr$,
    $sr$Kratovo Old Town$sr$,
    $sr$Средновековен рударски град каде што камени мостови се вијат над стари кратери, а кули паметат злато.$sr$,
    $sr$Medieval mining town where stone bridges arch over ancient craters and Ottoman towers guard memories of gold.$sr$,
    $sr$Изградено во и околу изгаснати вулкански кратери, Кратово ја пркоси логиката на обичните градови. Улици тунелираат низ карпа, мостови скокаат преку бездни што некогаш биле оган, а средновековните кули — дванаесет некогаш, шест преживеани — потсетуваат на златото и среброто. Отомански куќи се тискаат крај Кратовска Река. Околината ги носи лузните на вулканот: чудни карпи, кратерски езера, ридови во бои што обичната геологија не ги прави. Шетајте по мостовите во самрак. Некое богатство оди подлабоко од златото.$sr$,
    $sr$Built in and around extinct volcanic craters, Kratovo defies the logic of conventional towns. Streets tunnel through rock, bridges leap over chasms once filled with fire, and medieval towers—twelve of them originally, six surviving—stand as reminders of the gold and silver that made this place wealthy beyond measure. Ottoman-era houses crowd along the Kratovska River, their wooden balconies jutting over waters that once powered ore-crushing mills. The surrounding landscape bears the scars and beauties of volcanic origin: bizarre rock formations, crater lakes, and hills of colors no ordinary geology produces. The ride to Kratovo winds through terrain that seems designed by surrealists, arriving at a town that somehow blends mining history, volcanic drama, and Ottoman charm into something entirely unique. Wander the bridges at dusk. Listen for echoes of hammers on ore. Remember that some wealth runs deeper than gold.$sr$,
    $sr$Камени мостови кон заборавени времиња$sr$,
    $sr$Stone bridges to forgotten eras$sr$,
    array[$sr$Кратовската баница мора да се проба — прашајте во која било фурна$sr$, $sr$Кулите се качуваат за поглед од работ на кратерот — не е за страв од висина$sr$, $sr$Спојте го со Куклица за цел ден геолошко чудо$sr$]::text[],
    array[$sr$The town's famous 'Kratovska banitsa' pastry demands sampling—ask at any bakery$sr$, $sr$The medieval towers can be climbed for crater-rim views—vertigo-sufferers beware$sr$, $sr$Combine with Kuklica stone dolls for a full day of geological wonder$sr$]::text[],
    $sr$draft$sr$::public.publish_status,
    34,
    $sr$machine$sr$::public.translation_status
  ),
(
    $sr$kuklica-stone-dolls$sr$,
    $sr$East$sr$::public.region,
    array[$sr$Nature$sr$, $sr$Hidden Gem$sr$, $sr$Adventure$sr$]::text[],
    42.05,
    22.02,
    $sr$Куклица$sr$,
    $sr$Kuklica Stone Dolls$sr$,
    $sr$Природни камени столбови како скаменети свадбари, замрзнати од легенда во вечна тишина.$sr$,
    $sr$Natural rock pillars rising like petrified wedding guests, frozen by legend into eternal stone silence.$sr$,
    $sr$Според легендата, младоженец не можел да избере меѓу две невести, па ги поканил двете. Кога првата го видела со другата, клетвата ја скаменила целата свадба. Без разлика дали верувате во клетви или во трпеливата уметност на ерозијата, ефектот е ист: над 120 столба се издигаат од земјата како фигури замрзнати среде веселба. Некои се високи над 10 метри, со „глави“ неверојатно наместени на изедени „вратови“. Патот дотука минува низ осамена околина што го гради исчекувањето. Кога куклите ќе се појават, и најскептичниот застанува.$sr$,
    $sr$According to local legend, a young man couldn't choose between two brides, so he invited both to his wedding. When the first bride saw him marrying another, her curse turned the entire gathering to stone. Whether you believe in curses or prefer erosion's patient artistry, the effect is the same: over 120 stone pillars rise from the earth like figures frozen mid-celebration. Some stand over 10 meters tall, their 'heads' balanced improbably on eroded 'necks,' their forms suggesting dancers, priests, grieving mothers. The surrounding landscape adds to the surreal atmosphere—volcanic soil in unusual colors, sparse vegetation that seems deliberately theatrical. The road here crosses lonely countryside that builds anticipation for the reveal. When the 'dolls' finally appear, even the most skeptical visitor pauses. Some places defy explanation. Some legends, told often enough, become truer than fact.$sr$,
    $sr$Легенди издлабени во камен$sr$,
    $sr$Legends carved in stone$sr$,
    array[$sr$Златниот час ги претвора столбовите во килибарни скулптури$sr$, $sr$Нема објекти — понесете вода и удобни чевли$sr$, $sr$Водачите во Кратово ја знаат целата легенда и геологијата$sr$]::text[],
    array[$sr$Golden hour transforms the pillars into amber sculptures—time your visit accordingly$sr$, $sr$The site has no facilities—bring water and comfortable walking shoes$sr$, $sr$Local guides in Kratovo can share the full legend and geological explanations$sr$]::text[],
    $sr$draft$sr$::public.publish_status,
    35,
    $sr$machine$sr$::public.translation_status
  ),
(
    $sr$tetovo-arabati-baba-tekke$sr$,
    $sr$West$sr$::public.region,
    array[$sr$Cultural$sr$, $sr$Hidden Gem$sr$, $sr$Views$sr$]::text[],
    42,
    20.97,
    $sr$Арабати Баба Теќе$sr$,
    $sr$Arabati Baba Tekke$sr$,
    $sr$Мистичен бекташки комплекс каде што суфиските обичаи се мешаат со градина и барање.$sr$,
    $sr$Mystical Bektashi dervish compound where Sufi traditions blend with garden serenity and spiritual seeking.$sr$,
    $sr$Во сенката на Шар Планина, Арабати Баба Теќе нуди духовно прибежиште од XV век. Овој бекташки комплекс — еден од најголемите и најзачуваните на Балканот — опфаќа молитвени сали, турбиња, конаци и градини со речиси невозможна тишина. Редот ги меша суфиската мистика, поезијата како молитва и гостопримството како практика. Шетајќи, среќавате резбани дрвени решетки, насликани тавани и нишани на баратели што нашле мир меѓу овие ѕидови. Чуварот сè уште пречекува со турско кафе и разговор што се врти од историја кон природата на барањето. Пристигнете тивко. Собујте се на прагот.$sr$,
    $sr$In the shadow of the Šar Mountains, the Arabati Baba Tekke has offered spiritual refuge since the 15th century. This Bektashi dervish compound—one of the largest and best-preserved in the Balkans—encompasses prayer halls, tombs, guest houses, and gardens of almost impossible tranquility. The Bektashi order blends Sufi mysticism with unique traditions: whirling meditation, poetry as prayer, hospitality as spiritual practice. Walking these grounds, you encounter carved wooden screens, painted ceilings depicting the cosmos, and tombstones marking centuries of seekers who found peace within these walls. The keeper still welcomes visitors, offering Turkish coffee and conversations that spiral from history to philosophy to the nature of seeking itself. The road from Skopje crosses the Polog valley, mountains rising on all sides. Arrive quietly. Remove your shoes at the threshold. Some places require approaching with the soul already open.$sr$,
    $sr$Каде што душите се вртат кон бесконечното$sr$,
    $sr$Where souls spin toward the infinite$sr$,
    array[$sr$Облечете се скромно — ова е активно духовно место$sr$, $sr$Гостопримството на чуварот често вклучува чај — прифатете со благодарност$sr$, $sr$Спојте го со Шарената џамија во Тетово за цел ден полошко наследство$sr$]::text[],
    array[$sr$Dress modestly—this remains an active spiritual site deserving respect$sr$, $sr$The keeper's hospitality often includes tea—accept graciously$sr$, $sr$Combine with Painted Mosque in Tetovo for a full day of Polog spiritual heritage$sr$]::text[],
    $sr$draft$sr$::public.publish_status,
    36,
    $sr$machine$sr$::public.translation_status
  )
  on conflict (slug) do update set
    region = excluded.region,
