  )
  values
(
    $sr$eastern-waterfalls-loop$sr$,
    $sr$East$sr$::public.region,
    $sr$Moderate$sr$::public.difficulty,
    85,
    $sr$Источна јамка на водопадите$sr$,
    $sr$Eastern Waterfalls Loop$sr$,
    $sr$Од Струмица до Колешино, Смоларе и Водочкиот манастир: слапови и духовни застанувања.$sr$,
    $sr$From Strumica to Kolesino, Smolare, Vodoča Monastery: Cascading wonders and spiritual stops.$sr$,
    $sr$Оваа источна одисеја минува низ подножјето на Беласица и ги врзува најспектакуларните водопади со древни манастири што виделе илјада години молитви. Патот се вие низ села каде што времето тече како самите реки. Од 39-метарскиот слап на Смоларе до тивката песна на Колешино, од византиската тишина на Водоча до висините на Цареви Кули, рутата ги плете водата, каменот, верата и патиштата што ги спојуваат.$sr$,
    $sr$This eastern odyssey threads through the lush Belasica foothills, connecting Macedonia's most spectacular waterfalls with ancient monasteries that have witnessed a millennium of prayers. The road winds through villages where time flows like the rivers themselves—slowly, deliberately, with purpose. From the 39-meter cascade of Smolare to the gentle song of Kolesino, from the Byzantine silence of Vodoča to the panoramic heights of Carevi Kuli, this route weaves together the elements that make eastern Macedonia unforgettable: water, stone, faith, and the roads that connect them all.$sr$,
    $sr$Каде што водите паѓаат, а душите се издигаат$sr$,
    $sr$Where waters fall and souls rise$sr$,
    $sr$4–5 часа$sr$,
    $sr$4-5 hours$sr$,
    array[$sr$Два од највисоките водопади во Македонија во една вожња$sr$, $sr$Манастир стар илјада години со фрески што светат$sr$, $sr$Вијугави планински патишта низ дабови шуми$sr$, $sr$Селски крчми со свежа пастрмка$sr$]::text[],
    array[$sr$Two of Macedonia's tallest waterfalls in one ride$sr$, $sr$1000-year-old monastery with glowing frescoes$sr$, $sr$Twisting mountain roads through oak forests$sr$, $sr$Local village taverns serving fresh trout$sr$]::text[],
    array[$sr$Почувствувајте ја маглата од водопадите на лицето$sr$, $sr$Шетајте низ древни манастирски градини во тишина$sr$, $sr$Возете ги вијугавите патишта на Беласица$sr$, $sr$Јадете свежа пастрмка во селски механи$sr$, $sr$Фатете ја златната светлина низ шумските крошни$sr$]::text[],
    array[$sr$Feel the mist of cascading waterfalls on your face$sr$, $sr$Wander through ancient monastery gardens in silence$sr$, $sr$Ride the twisting Belasica mountain roads$sr$, $sr$Feast on fresh trout at village tavernas$sr$, $sr$Capture golden light through forest canopies$sr$]::text[],
    array[$sr$Чакал на фиоките кај Смоларе — возете будно и мазно$sr$, $sr$Утринската магла прави волшебни фотографии од водопадите$sr$, $sr$Посетата на манастир бара скромна облека$sr$, $sr$Наполнете во Струмица — на планинските патишта нема пумпи$sr$]::text[],
    array[$sr$Gravel on hairpins near Smolare—ride alert and smooth$sr$, $sr$Morning mist creates magical waterfall photos$sr$, $sr$Monastery visits require modest dress$sr$, $sr$Fill up in Strumica—no fuel stations on the mountain roads$sr$]::text[],
    $sr$[{"name":"Village café near Kolesino","description_mk":"Краток одмор со домашни пити и силно кафе","description_en":"Quick rest with local pies and strong coffee"},{"name":"Trout taverna by Smolare","description_mk":"Свежа речна пастрмка на отворен оган","description_en":"Fresh river trout grilled over open flame"},{"name":"Monastery guesthouse","description_mk":"Едноставен прекусед во мирни градини","description_en":"Simple refreshments in peaceful gardens"}]$sr$::jsonb,
    $sr${"elevation":"400 м – 1.200 м (искачување 800 м)","roadCondition":"Асфалт со делници чакал кај водопадите","bestSeason":"Од април до октомври","fuelStops":"Наполнете во Струмица пред тргнување"}$sr$::jsonb,
    $sr${"elevation":"400m - 1,200m (800m climb)","roadCondition":"Asphalt with gravel sections near waterfalls","bestSeason":"April to October","fuelStops":"Fill up in Strumica before departure"}$sr$::jsonb,
    $sr$draft$sr$::public.publish_status,
    1,
    $sr$machine$sr$::public.translation_status
  ),
(
    $sr$western-lakes-tour$sr$,
    $sr$West$sr$::public.region,
    $sr$Challenging$sr$::public.difficulty,
    120,
    $sr$Тура на западните езера$sr$,
    $sr$Western Lakes Tour$sr$,
    $sr$Од Охрид преку Галичица и Трпејца до Св. Наум: езерски мир и древни патеки.$sr$,
    $sr$Ohrid to Galicica Pass, Trpejca Beach, Sv. Naum: Lake serenity and ancient paths.$sr$,
    $sr$Оваа јамка ги прегрнува двете езера под заштита на УНЕСКО и се качува низ Националниот парк Галичица каде што воздухот се разредува, а погледите се множат. Почнете на древниот брег на Охрид, искачете ги легендарните фиоки на превојот каде што двете езера треперат долу, спуштете се до рибарското село Трпејца и завршете кај Свети Наум, каде што пауни шетаат, а извори избиваат од легенда. Секој километар нуди глетки што со векови ги движеле поетите и аџиите.$sr$,
    $sr$This iconic loop embraces both of Macedonia's UNESCO-protected lakes, climbing through Galicica National Park where the air thins and perspectives multiply. Begin at Lake Ohrid's ancient shores, ascend the legendary hairpins of Galicica Pass where two lakes shimmer below, descend to the fishing village of Trpejca, and conclude at St. Naum Monastery where peacocks roam and springs bubble up from legend. Every kilometer offers views that have inspired poets, painters, and pilgrims for millennia. This isn't just a ride—it's a journey through the soul of the Balkans.$sr$,
    $sr$Каде што две езера ја огледуваат вечноста$sr$,
    $sr$Where two lakes mirror eternity$sr$,
    $sr$5–6 часа$sr$,
    $sr$5-6 hours$sr$,
    array[$sr$Превој Галичица со панорама на две езера$sr$, $sr$Средновековен манастир со природни извори$sr$, $sr$Крајезерска кујна во Трпејца$sr$, $sr$Над 30 фиоки чисто задоволство за возење$sr$]::text[],
    array[$sr$Galicica Pass with dual-lake panoramas$sr$, $sr$Medieval monastery with natural springs$sr$, $sr$Lakeside village cuisine at Trpejca$sr$, $sr$30+ hairpin turns of pure riding joy$sr$]::text[],
    array[$sr$Совладајте ги легендарните фиоки на Галичица$sr$, $sr$Гледајте две древни езера од висина на облак$sr$, $sr$Јадете летен рибен на скара во крајезерски механи$sr$, $sr$Гледајте ги пауните кај Свети Наум$sr$, $sr$Одете со брод до тиркизните извори$sr$]::text[],
    array[$sr$Conquer Galicica's legendary hairpin bends$sr$, $sr$Gaze at two ancient lakes from cloud height$sr$, $sr$Dine on grilled letnik fish at lakeside tavernas$sr$, $sr$Watch peacocks strut at St. Naum Monastery$sr$, $sr$Take a boat to the turquoise springs$sr$]::text[],
    array[$sr$Растресит чакал на врвот на Галичица — не претерувајте со кривините$sr$, $sr$Залезот од превојот е легендарен, но слегувањето е во темница$sr$, $sr$Резервирајте ручек во Трпејца летос$sr$, $sr$Свети Наум е полн напладне — дојдете рано или доцна$sr$]::text[],
    array[$sr$Loose gravel on Galicica summit—don't overcook corners$sr$, $sr$Sunset from the pass is legendary but means riding down in dark$sr$, $sr$Book Trpejca restaurants for lunch in summer$sr$, $sr$St. Naum gets crowded midday—arrive early or late$sr$]::text[],
    $sr$[{"name":"Lakeside taverna at Trpejca","description_mk":"Свеж летен рибен со поглед на езерото — резервирајте летос","description_en":"Fresh letnik fish with lake views—book ahead in summer"},{"name":"Summit café at Galicica Pass","description_mk":"Кафе и пецива со панорама на двете езера","description_en":"Coffee and pastries with dual-lake panorama"},{"name":"St. Naum restaurant","description_mk":"Традиционална кујна во манастирските градини","description_en":"Traditional cuisine in monastery gardens"}]$sr$::jsonb,
    $sr${"elevation":"695 м – 1.568 м (искачување 873 м)","roadCondition":"Асфалт со дамки чакал на врвот","bestSeason":"Од мај до септември","fuelStops":"Наполнете во Охрид пред искачувањето"}$sr$::jsonb,
    $sr${"elevation":"695m - 1,568m (873m climb)","roadCondition":"Paved with gravel patches on summit","bestSeason":"May to September","fuelStops":"Fill up in Ohrid before the climb"}$sr$::jsonb,
    $sr$draft$sr$::public.publish_status,
    2,
    $sr$machine$sr$::public.translation_status
  ),
(
    $sr$central-canyon-ride$sr$,
    $sr$Central$sr$::public.region,
    $sr$Moderate$sr$::public.difficulty,
    140,
    $sr$Возење низ централниот кањон$sr$,
    $sr$Central Canyon Ride$sr$,
    $sr$Од кањонот Матка до Маркови Кули: драмски клисури и историски кули.$sr$,
    $sr$Matka Canyon to Marko's Towers: Dramatic gorges and historic towers.$sr$,
    $sr$На неколку минути од главниот град лежи геолошка и историска драма што се мери со која било во Европа. Рутата ја врзува Матка — каде што вапненички карпи тонат во смарагдна вода, а средновековни манастири се држат за невозможни ѕидови — со легендарните Маркови Кули кај Прилеп, урнатини врзани за најголемиот балкански народен јунак. Меѓу нив патот минува од кањон во рамнина и планина, низ градови каде што римската и византиската историја спијат веднаш под површината.$sr$,
    $sr$Just minutes from Macedonia's capital lies geological and historical drama that rivals anywhere in Europe. This route connects Matka Canyon—where limestone cliffs plunge into emerald waters and medieval monasteries cling to impossible walls—with the legendary Marko's Towers near Prilep, fortress ruins associated with the Balkans' greatest folk hero. Between them, the road traverses landscapes that shift from canyon to plain to mountain, through towns where Roman and Byzantine history sleeps just beneath the surface. Pack your sense of wonder; you'll need every ounce.$sr$,
    $sr$Каде што каменот раскажува приказни за кралеви$sr$,
    $sr$Where stone tells stories of kings$sr$,
    $sr$6–7 часа$sr$,
    $sr$6-7 hours$sr$,
    array[$sr$Истражување на пештерата Врело$sr$, $sr$Пешачење до тврдината на кралот Марко$sr$, $sr$Кајак во кањонот Матка$sr$, $sr$Византиски цркви со древни фрески$sr$]::text[],
    array[$sr$Cave exploration at Vrelo Cave$sr$, $sr$Hiking to legendary King Marko's fortress$sr$, $sr$Kayaking options in Matka Canyon$sr$, $sr$Byzantine churches with ancient frescoes$sr$]::text[],
    array[$sr$Веслајте кајак меѓу високите вапненички ѕидови$sr$, $sr$Истражете ги сталактитите на Врело$sr$, $sr$Искачете се до легендарните урнатини на Марко$sr$, $sr$Фотографирајте манастири залепени за карпи$sr$, $sr$Пијте кафе над смарагдната вода на кањонот$sr$]::text[],
    array[$sr$Kayak between towering limestone canyon walls$sr$, $sr$Explore Vrelo Cave's ancient stalactites$sr$, $sr$Hike to Marko's legendary fortress ruins$sr$, $sr$Photograph monasteries clinging to cliff faces$sr$, $sr$Sip coffee overlooking emerald canyon waters$sr$]::text[],
    array[$sr$Паркингот на Матка е мал — викендите стигнете пред 10 часот$sr$, $sr$Патот за Прилеп летос е жежок — пијте вода$sr$, $sr$Пешачењето до Маркови Кули трае 45–60 минути — понесете вода$sr$, $sr$Вечерната светлина на Матка е спектакл за фотографии$sr$]::text[],
    array[$sr$Matka parking is limited—arrive before 10am on weekends$sr$, $sr$The Prilep road can be hot in summer—hydrate well$sr$, $sr$Marko's Towers hike takes 45-60 min—pack water$sr$, $sr$Evening light at Matka is spectacular for photos$sr$]::text[],
    $sr$[{"name":"Canyon View Restaurant at Matka","description_mk":"Пастрмка на скара и кафе со поглед на смарагдна вода","description_en":"Grilled trout and coffee with emerald water views"},{"name":"Prilep town center","description_mk":"Локални фури со свежа бурек и ајран","description_en":"Local bakeries with fresh burek and ayran"},{"name":"Village kafana near Marko's Towers","description_mk":"Традиционална кафеана со ладни пијалаци по пешачењето","description_en":"Traditional tavern with cold drinks after the hike"}]$sr$::jsonb,
    $sr${"elevation":"300 м – 850 м (искачување 550 м)","roadCondition":"Одличен асфалт цел пат","bestSeason":"Цела година (избегнувајте зима за пешачењето до Марко)","fuelStops":"Неколку пумпи по главниот пат"}$sr$::jsonb,
    $sr${"elevation":"300m - 850m (550m climb)","roadCondition":"Excellent asphalt throughout","bestSeason":"Year-round (avoid winter for Marko's hike)","fuelStops":"Multiple stations along main road"}$sr$::jsonb,
    $sr$draft$sr$::public.publish_status,
    3,
    $sr$machine$sr$::public.translation_status
