(
    $sr$northern-mountain-pass$sr$,
    $sr$West$sr$::public.region,
    $sr$Challenging$sr$::public.difficulty,
    95,
    $sr$Северен планински превој$sr$,
    $sr$Northern Mountain Pass$sr$,
    $sr$Од Мавровско Езеро до превојот Бистра: борови шуми и високи свиоци.$sr$,
    $sr$Mavrovo Lake to Bistra Pass: Pine forests and high twists.$sr$,
    $sr$Оваа висока одисеја ја спојува мирната убавина на Мавровското Езеро — со познатата потоната црква — со суровата дивина на превојот Бистра, каде што патиштата се сечени против волјата на природата. Рутата се качува низ борови шуми што издишуваат стар мирис, покрај овчарски колиби непроменети со векови, до висини каде што воздухот ги изострува сетилата. Ова е планинското срце на Македонија, диво и нескротено. Не е за слаби срца, но ги менува оние што се осмелуваат.$sr$,
    $sr$This high-altitude odyssey combines the serene beauty of Mavrovo Lake—with its famous drowned church rising from the waters—with the raw wilderness of Bistra Mountain Pass where roads were carved against nature's will. The route climbs through pine forests that exhale ancient perfume, past shepherds' huts unchanged for centuries, up to elevations where the air sharpens every sense. This is Macedonia's mountain heart, wild and untamed, where wolves still hunt and roads still demand respect. Not for the faint of heart, but transformative for those who dare.$sr$,
    $sr$Каде што орлите кружат под тркалата$sr$,
    $sr$Where eagles circle below your wheels$sr$,
    $sr$4–5 часа$sr$,
    $sr$4-5 hours$sr$,
    array[$sr$Познатата потоната црква во Мавровското Езеро$sr$, $sr$Високи фиоки без заштитна ограда$sr$, $sr$Алпски ливади со диви коњи$sr$, $sr$Јагне во планински колиби$sr$]::text[],
    array[$sr$Famous drowned church in Mavrovo Lake$sr$, $sr$High-altitude hairpins with no guardrails$sr$, $sr$Alpine meadows with wild horses$sr$, $sr$Mountain hut lamb feasts$sr$]::text[],
    array[$sr$Фотографирајте ја иконичната потоната црква на Маврово$sr$, $sr$Возете фиоки издлабени во диви планински страни$sr$, $sr$Јадете бавно печено јагне во колиби$sr$, $sr$Барајте диви коњи на алпските ливади$sr$, $sr$Дишете го најчистиот планински воздух на Балканот$sr$]::text[],
    array[$sr$Photograph the iconic drowned church at Mavrovo$sr$, $sr$Ride hairpins carved into wild mountainsides$sr$, $sr$Feast on slow-roasted lamb at mountain huts$sr$, $sr$Watch for wild horses in alpine meadows$sr$, $sr$Breathe the purest mountain air in the Balkans$sr$]::text[],
    array[$sr$Времето се менува брзо — понесете целосна водоотпорна опрема$sr$, $sr$На Бистра нема огради — почитувајте го работ$sr$, $sr$Овчарите имаат предност — застанете за стадата$sr$, $sr$Гориво во Маврови Анови — понатаму нема ништо$sr$]::text[],
    array[$sr$Weather changes rapidly—pack full waterproofs$sr$, $sr$No guardrails on Bistra—focus and respect the edge$sr$, $sr$Shepherds have right of way—stop for flocks$sr$, $sr$Fuel in Mavrovi Anovi—nothing beyond$sr$]::text[],
    $sr$[{"name":"Mountain hut at Mavrovo","description_mk":"Топол одмор со чај и бавно печено јагне","description_en":"Cozy rest with tea and slow-roasted lamb"},{"name":"Lakeside restaurant Mavrovo","description_mk":"Свежа пастрмка со планинска панорама","description_en":"Fresh trout with mountain panoramas"},{"name":"Shepherd's koliba on Bistra","description_mk":"Едноставно сирење и леб со вистинско гостопримство","description_en":"Simple cheese and bread with genuine hospitality"}]$sr$::jsonb,
    $sr${"elevation":"1.200 м – 1.800 м (искачување 600 м)","roadCondition":"Асфалт, но тесен, без огради на врвот","bestSeason":"Од јуни до септември (снегот го затвора превојот зима)","fuelStops":"Последно гориво во селото Маврови Анови"}$sr$::jsonb,
    $sr${"elevation":"1,200m - 1,800m (600m climb)","roadCondition":"Paved but narrow with no guardrails on summit","bestSeason":"June to September (snow blocks pass in winter)","fuelStops":"Last fuel in Mavrovi Anovi village"}$sr$::jsonb,
    $sr$draft$sr$::public.publish_status,
    4,
    $sr$machine$sr$::public.translation_status
  ),
(
    $sr$southern-winery-escape$sr$,
    $sr$Central$sr$::public.region,
    $sr$Easy$sr$::public.difficulty,
    70,
    $sr$Јужно винарско бегство$sr$,
    $sr$Southern Winery Escape$sr$,
    $sr$Од Демир Капија до Попова Кула: Вардарска клисура и лозја за душата.$sr$,
    $sr$Demir Kapija to Popova Kula: Vardar gorge and soulful vines.$sr$,
    $sr$Ова цивилизирано бегство ја спојува геолошката драма со задоволството на лозјето. Клисурата Железна порта во Демир Капија ја покажува силата на природата да пресече планина, а лозјата на Попова Кула го покажуваат дарот на човекот да извади убавина од сончева земја. Рутата го следи Вардар низ едни од најдраматичните предели, покрај ѕидови за качување и брзаци за кајак, па се качува во виногорје каде што вранецот расте уште од римско време. Завршете со дегустација над бескрајни редови лозје — сте ја заслужиле.$sr$,
    $sr$This civilized escape combines geological drama with viticultural pleasure. The Iron Gate gorge of Demir Kapija showcases nature's power to carve through mountains, while the vineyards of Popova Kula demonstrate humanity's gift for coaxing beauty from sun-warmed earth. The route follows the Vardar River through some of Macedonia's most dramatic scenery, past rock climbing walls and kayaking rapids, before ascending into wine country where Vranec grapes have grown since Roman times. End your ride with a tasting overlooking endless vine rows—you've earned it.$sr$,
    $sr$Каде што реките издлабиле патишта за виното да тече$sr$,
    $sr$Where rivers carved paths for wine to flow$sr$,
    $sr$3–4 часа$sr$,
    $sr$3-4 hours$sr$,
    array[$sr$Вапненичка клисура со карпи од 500 метри$sr$, $sr$Наградувани македонски вина$sr$, $sr$Места за пикник крај реката$sr$, $sr$Качување и кајак$sr$]::text[],
    array[$sr$Limestone gorge with 500m cliffs$sr$, $sr$Award-winning Macedonian wines$sr$, $sr$Riverside picnic spots$sr$, $sr$Rock climbing and kayaking options$sr$]::text[],
    array[$sr$Зачудете се на вапненичките ѕидови на Железната порта$sr$, $sr$Пробајте наградуван вранец и розе$sr$, $sr$Пикник крај брзиот Вардар$sr$, $sr$Гледајте качувачи по древни карпи$sr$, $sr$Наздравете го залезот над бескрајни лозја$sr$]::text[],
    array[$sr$Marvel at the Iron Gate's towering limestone walls$sr$, $sr$Taste award-winning Vranec and rosé wines$sr$, $sr$Picnic by the rushing Vardar River$sr$, $sr$Watch rock climbers scale ancient cliff faces$sr$, $sr$Toast sunset over endless vineyard rows$sr$]::text[],
    array[$sr$Одредете трезен возач за посетата на винаријата$sr$, $sr$Утринската светлина ги осветлува источните карпи на клисурата$sr$, $sr$Резервирајте дегустација однапред за целото искуство$sr$, $sr$Патот низ клисурата има малку застанувања — извидете ги$sr$]::text[],
    array[$sr$Designate a sober rider for the winery visit$sr$, $sr$Morning light illuminates the gorge's eastern cliffs$sr$, $sr$Book winery tastings in advance for full experience$sr$, $sr$The gorge road has limited stops—scout pull-offs$sr$]::text[],
    $sr$[{"name":"Popova Kula Winery Restaurant","description_mk":"Гурманска македонска кујна со наградувани вина","description_en":"Gourmet Macedonian cuisine with award-winning wines"},{"name":"Riverside picnic area at Demir Kapija","description_mk":"Понесете свое и јадете крај брзата вода","description_en":"Bring your own and dine by rushing waters"},{"name":"Local kafana in Negotino","description_mk":"Традиционално мезе и локални тиквешки вина","description_en":"Traditional meze and local Tikveš wines"}]$sr$::jsonb,
    $sr${"elevation":"150 м – 450 м (благо искачување од 300 м)","roadCondition":"Одличен асфалт цел пат","bestSeason":"Цела година (есен за бербата)","fuelStops":"Демир Капија и Неготино"}$sr$::jsonb,
    $sr${"elevation":"150m - 450m (gentle 300m climb)","roadCondition":"Excellent asphalt throughout","bestSeason":"Year-round (autumn for grape harvest)","fuelStops":"Demir Kapija and Negotino town"}$sr$::jsonb,
    $sr$draft$sr$::public.publish_status,
    5,
    $sr$machine$sr$::public.translation_status
  ),
(
    $sr$pelister-peaks-hike$sr$,
    $sr$West$sr$::public.region,
    $sr$Moderate$sr$::public.difficulty,
    80,
    $sr$Пешачење по врвовите на Пелистер$sr$,
    $sr$Pelister Peaks Hike$sr$,
    $sr$Патеки на Баба Планина со видиковци и ендемски моликови шуми.$sr$,
    $sr$Baba Mountain trails with overlooks and endemic Molika pine forests.$sr$,
    $sr$Првиот национален парк во Македонија нуди возење и пешачење што ве врзува со предел стар пет милиони години. Ендемската молика — речиси никаде на друго место на Земјата — гледала ледени доба како доаѓаат и си одат, и сега гледа како вие се виете низ нејзините древни шуми. Рутата ги спојува драмските планински патишта со можност да го оставите моторот и да продолжите пеш: ледничките Очи на Пелистер, највисоките врвови на Баба и видиковци од каде што Грција трепери на хоризонтот. Дојдете заради патиштата; останете заради перспективата што ја дава само висината.$sr$,
    $sr$Macedonia's first national park offers riding and hiking that connects you with a landscape five million years in the making. The endemic Molika pine—found almost nowhere else on Earth—has watched ice ages come and go, and now watches you wind through its ancient groves. This route combines dramatic mountain roads with opportunities to leave the bike and explore on foot: the glacial 'Eyes of Pelister' lakes, the highest peaks of Baba Mountain, and viewpoints where Greece shimmers on the horizon. Come for the roads; stay for the perspective only altitude provides.$sr$,
    $sr$Каде што пет милиони години трпение цветаат$sr$,
    $sr$Where five million years of patience bloom$sr$,
    $sr$5–6 часа$sr$,
    $sr$5-6 hours$sr$,
    array[$sr$Ендемски моликови шуми$sr$, $sr$Пешачење до ледничките езера (2–3 часа)$sr$, $sr$Поглед кон Грција во ведар ден$sr$, $sr$Преноќиште во планински колиби$sr$]::text[],
    array[$sr$Endemic Molika pine forests$sr$, $sr$Glacial lakes hike (2-3 hours)$sr$, $sr$Views to Greece on clear days$sr$, $sr$Mountain hut accommodation available$sr$]::text[],
    array[$sr$Шетајте меѓу молики стари пет милиони години$sr$, $sr$Искачете се до ледничките Очи на Пелистер$sr$, $sr$Гледајте кон Грција од високите видиковци$sr$, $sr$Преноќете во вистински планински колиби$sr$, $sr$Берете диви бобинки покрај августовските патишта$sr$]::text[],
    array[$sr$Walk among five-million-year-old Molika pines$sr$, $sr$Hike to the glacial 'Eyes of Pelister' lakes$sr$, $sr$Gaze toward Greece from the high overlooks$sr$, $sr$Stay overnight in authentic mountain huts$sr$, $sr$Pick wild berries along the August roadsides$sr$]::text[],
    array[$sr$Пешачењето до езерата додава 2–3 часа — планирајте$sr$, $sr$Температурата паѓа околу 10 степени од долината до врвот$sr$, $sr$Августовските диви бобинки се совршена ужина покрај патеката$sr$, $sr$Колибите нудат едноставно ноќевање — резервирајте$sr$]::text[],
    array[$sr$Glacial lakes hike adds 2-3 hours—budget accordingly$sr$, $sr$Temperature drops 10°C from valley to summit$sr$, $sr$August wild berries make perfect trailside snacks$sr$, $sr$Mountain huts offer simple overnight stays—book ahead$sr$]::text[],
    $sr$[{"name":"Mountain hut Kopanki","description_mk":"Јак планински чорба и топли кревети на висина","description_en":"Hearty mountain stew and warm beds at altitude"},{"name":"Bitola old bazaar","description_mk":"Кафулиња од отоманско време со силно турско кафе","description_en":"Ottoman-era cafés with strong Turkish coffee"},{"name":"Pelister park entrance café","description_mk":"Лесен прекусед пред или по пешачењето","description_en":"Light refreshments before or after the hike"}]$sr$::jsonb,
    $sr${"elevation":"600 м – 2.200 м (искачување 1.600 м до езерата)","roadCondition":"Асфалт до влезот на паркот, чакал по планинските патеки","bestSeason":"Од јуни до октомври (снегот ги покрива врвовите зима)","fuelStops":"Битола, пред влезот во паркот"}$sr$::jsonb,
    $sr${"elevation":"600m - 2,200m (1,600m climb to lakes)","roadCondition":"Paved to park entrance, gravel on mountain tracks","bestSeason":"June to October (snow covers peaks in winter)","fuelStops":"Bitola city before entering the park"}$sr$::jsonb,
    $sr$draft$sr$::public.publish_status,
    6,
    $sr$machine$sr$::public.translation_status
  ),
(
    $sr$prespa-hidden-shores$sr$,
    $sr$West$sr$::public.region,
    $sr$Moderate$sr$::public.difficulty,
    65,
    $sr$Скриени брегови на Преспа$sr$,
    $sr$Prespa Hidden Shores$sr$,
    $sr$Од Преспанско Езеро до островот Голем Град: тивки води и древни тајни.$sr$,
    $sr$Lake Prespa to Golem Grad Island: Quiet waters and ancient mysteries.$sr$,
    $sr$Ова мистично патување ја истражува срамежливата сестра на Охрид — потивка, потаинствена и бесконечно поконтемплативна. Патот ги следи бреговите на Преспа низ јаболкници и напуштени села, покрај византиски урнатини и колонии пеликани, кон енигматичниот Голем Град каде што римски храмови спијат меѓу илјадници водни змии. Ова не е рута за оние што бараат толпа или удобност; за души што наоѓаат мир во самотија и чудо во заборавеното. Бродовите за Голем Град тргнуваат од крајезерски села и преминуваат вода што ја делат три држави.$sr$,
    $sr$This mystical journey explores Macedonia's shy sibling lake—quieter, more mysterious, and infinitely more contemplative than famous Ohrid. The road traces Prespa's shores through apple orchards and abandoned villages, past Byzantine ruins and pelican colonies, toward the enigmatic Golem Grad island where Roman temples sleep among thousands of water snakes. This isn't a route for those seeking crowds or comforts; it's for souls who find peace in solitude and wonder in the forgotten. Boats to Golem Grad depart from lakeside villages, crossing waters shared by three nations into a world time forgot.$sr$,
    $sr$Каде што змиите чуваат заборавени империи$sr$,
    $sr$Where serpents guard forgotten empires$sr$,
    $sr$4–5 часа$sr$,
    $sr$4-5 hours$sr$,
    array[$sr$Колонии пеликани во зори$sr$, $sr$Брод до остров населен со змии$sr$, $sr$Римски урнатини во дива природа$sr$, $sr$Погледи на границата на три држави$sr$]::text[],
    array[$sr$Pelican colonies at dawn$sr$, $sr$Boat trip to snake-inhabited island$sr$, $sr$Roman ruins in wild nature$sr$, $sr$Three-country border views$sr$]::text[],
    array[$sr$Гледајте ги пеликаните како полетуваат во зори$sr$, $sr$Преминете со брод вода што ја делат три држави$sr$, $sr$Истражете римски урнатини чувани од змии$sr$, $sr$Фотографирајте напуштени села што природата ги вратила$sr$, $sr$Вкусете го мирот на езеро што светот го заборавил$sr$]::text[],
    array[$sr$Watch pelicans take flight at dawn$sr$, $sr$Boat across waters shared by three nations$sr$, $sr$Explore Roman ruins guarded by serpents$sr$, $sr$Photograph abandoned villages reclaimed by nature$sr$, $sr$Taste the peace of a lake the world forgot$sr$]::text[],
    array[$sr$Проверете ги редовите на брод за Голем Град однапред$sr$, $sr$Змиите се безопасни — сепак носете затворени чевли$sr$, $sr$Зората и самракот носат најдобри средби со пеликани$sr$, $sr$Понесете сè — брегот има малку услуги$sr$]::text[],
    array[$sr$Check boat schedules to Golem Grad in advance$sr$, $sr$The snakes are harmless—wear closed shoes anyway$sr$, $sr$Dawn and dusk bring the best pelican sightings$sr$, $sr$Bring all supplies—the shore has few services$sr$]::text[],
    $sr$[{"name":"Apple orchard farm near Stenje","description_mk":"Свеж јаболков сок и даски локално сирење","description_en":"Fresh apple juice and local cheese platters"},{"name":"Fisherman's cottage at Konjsko","description_mk":"Едноставен крап на скара со мир на езерото","description_en":"Simple grilled carp with lakefront serenity"},{"name":"Village store at Resen","description_mk":"Наполнете залихи пред оддалечените брегови","description_en":"Stock up on supplies before remote shores"}]$sr$::jsonb,
    $sr${"elevation":"850 м – 1.050 м (благ брановиден терен)","roadCondition":"Асфалт со груби делови по крајезерските патишта","bestSeason":"Од април до октомври (пеликаните се најдобри напролет)","fuelStops":"Само Ресен — наполнете пред бреговите"}$sr$::jsonb,
    $sr${"elevation":"850m - 1,050m (gentle rolling terrain)","roadCondition":"Paved with some rough patches on lakeside roads","bestSeason":"April to October (pelicans best in spring)","fuelStops":"Resen town only—fill up before heading to shores"}$sr$::jsonb,
    $sr$draft$sr$::public.publish_status,
    7,
    $sr$machine$sr$::public.translation_status
  )
  on conflict (slug) do update set
    region = excluded.region,
    difficulty = excluded.difficulty,
    distance_km = excluded.distance_km,
    name_mk = excluded.name_mk,
    name_en = excluded.name_en,
    description_mk = excluded.description_mk,
    description_en = excluded.description_en,
    long_description_mk = excluded.long_description_mk,
    long_description_en = excluded.long_description_en,
    tagline_mk = excluded.tagline_mk,
    tagline_en = excluded.tagline_en,
    duration_mk = excluded.duration_mk,
    duration_en = excluded.duration_en,
    highlights_mk = excluded.highlights_mk,
    highlights_en = excluded.highlights_en,
    activities_mk = excluded.activities_mk,
    activities_en = excluded.activities_en,
    rider_tips_mk = excluded.rider_tips_mk,
    rider_tips_en = excluded.rider_tips_en,
    eat_and_rest = excluded.eat_and_rest,
    details_mk = excluded.details_mk,
    details_en = excluded.details_en,
    status = excluded.status,
    sort_order = excluded.sort_order,
    mk_status = excluded.mk_status
  where public.routes.updated_by is null;

  delete from public.route_spots rs
  using public.routes r
  where rs.route_id = r.id
    and r.updated_by is null
    and not exists (
      select 1
      from (
  select $sr$eastern-waterfalls-loop$sr$, $sr$kolesino-waterfall$sr$, 0::smallint, $sr$Застанете под слапот од 15 метри и почувствувајте ја лековитата магла$sr$, $sr$Stand beneath the 15m cascade and feel the healing mist$sr$
  union all
  select $sr$eastern-waterfalls-loop$sr$, $sr$smolare-waterfall$sr$, 1::smallint, $sr$Искачете се до платформата за највисокиот водопад во Македонија$sr$, $sr$Hike to the viewing platform for Macedonia's tallest waterfall$sr$
  union all
  select $sr$eastern-waterfalls-loop$sr$, $sr$vodoca-monastery$sr$, 2::smallint, $sr$Запалете свеќа и седнете во тишина стара илјада години$sr$, $sr$Light a candle and sit in the 1000-year silence$sr$
  union all
  select $sr$western-lakes-tour$sr$, $sr$galicica-pass$sr$, 0::smallint, $sr$Видете ја панорамата на двете езера од кафулето на врвот$sr$, $sr$View epic dual-lake panoramas from the summit café$sr$
  union all
  select $sr$western-lakes-tour$sr$, $sr$trpejca-beach$sr$, 1::smallint, $sr$Јадете свежа пастрмка на скара со стапала во езерото$sr$, $sr$Eat fresh grilled trout with your feet in the lake$sr$
  union all
  select $sr$western-lakes-tour$sr$, $sr$sv-naum-monastery$sr$, 2::smallint, $sr$Одете со брод до волшебните тиркизни извори$sr$, $sr$Take a boat ride to the magical turquoise springs$sr$
  union all
  select $sr$central-canyon-ride$sr$, $sr$matka-canyon$sr$, 0::smallint, $sr$Одете со брод во кристалните длабочини на Врело$sr$, $sr$Take the cave boat tour into Vrelo's crystal depths$sr$
  union all
  select $sr$central-canyon-ride$sr$, $sr$markos-towers$sr$, 1::smallint, $sr$Искачете се до тврдината и слушнете ги легендите за Крале Марко$sr$, $sr$Hike to the fortress and hear legends of King Marko$sr$
  union all
  select $sr$northern-mountain-pass$sr$, $sr$mavrovo-lake-loop$sr$, 0::smallint, $sr$Застанете пред потонатата црква што се издига од азурна вода$sr$, $sr$Stand before the drowned church rising from azure waters$sr$
  union all
  select $sr$northern-mountain-pass$sr$, $sr$bistra-mountain-pass$sr$, 1::smallint, $sr$Совладајте ги дивите фиоки каде што орлите летаат подолу$sr$, $sr$Conquer the wild hairpins where eagles soar below$sr$
  union all
  select $sr$southern-winery-escape$sr$, $sr$demir-kapija-gorge$sr$, 0::smallint, $sr$Застанете таму каде што Вардар ја пробил планината$sr$, $sr$Stand where the Vardar broke through the mountain$sr$
  union all
  select $sr$southern-winery-escape$sr$, $sr$popova-kula-winery$sr$, 1::smallint, $sr$Уживајте во дегустација на зајдисонце над лозјата$sr$, $sr$Savor a sunset wine tasting overlooking the vines$sr$
  union all
  select $sr$pelister-peaks-hike$sr$, $sr$pelister-viewpoint$sr$, 0::smallint, $sr$Гледајте како светот паѓа од работ на Баба Планина$sr$, $sr$Watch the world fall away at Baba Mountain's edge$sr$
  union all
  select $sr$pelister-peaks-hike$sr$, $sr$pelister-national-park$sr$, 1::smallint, $sr$Искачете се до ледничките Очи што го одразуваат бесконечното небо$sr$, $sr$Hike to the glacial 'Eyes' that reflect infinite sky$sr$
  union all
  select $sr$prespa-hidden-shores$sr$, $sr$prespa-lake-shore$sr$, 0::smallint, $sr$Гледајте ги пеликаните како цртаат кругови на утринското небо$sr$, $sr$Watch pelicans paint circles in the morning sky$sr$
  union all
  select $sr$prespa-hidden-shores$sr$, $sr$golem-grad-island$sr$, 1::smallint, $sr$Шетајте меѓу римски урнатини чувани од древни змии$sr$, $sr$Walk among Roman ruins guarded by ancient serpents$sr$
) src (route_slug, slug, position, things_mk, things_en)
      join public.spots s on s.slug = src.slug
      where src.route_slug = r.slug
        and s.id = rs.spot_id
    );

  insert into public.route_spots (route_id, spot_id, position, things_to_do_mk, things_to_do_en)
