  union all
  select $sr$western-lakes-tour$sr$, $sr$sv-naum-monastery$sr$, 2::smallint, $sr$Одете со брод до волшебните тиркизни извори$sr$, $sr$Take a boat ride to the magical turquoise springs$sr$
  union all
  select $sr$central-canyon-ride$sr$, $sr$matka-canyon$sr$, 0::smallint, $sr$Одете со брод во кристалните длабочини на Врело$sr$, $sr$Take the cave boat tour into Vrelo's crystal depths$sr$
  union all
  select $sr$central-canyon-ride$sr$, $sr$markos-towers$sr$, 1::smallint, $sr$Искачете се до тврдината и слушнете ги легендите за Крале Марко$sr$, $sr$Hike to the fortress and hear legends of King Marko$sr$
  union all
  select $sr$northern-mountain-pass$sr$, $sr$mavrovo-lake-loop$sr$, 0::smallint, $sr$Застанете пред потонатата црква што се издига од азурна вода$sr$, $sr$Stand before the drowned church rising from azure waters$sr$
  union all
  select $sr$northern-mountain-pass$sr$, $sr$bistra-mountain-pass$sr$, 1::smallint, $sr$Совладајте ги дивите фиоки каде што орлите летаат подолу$sr$, $sr$Conquer the wild hairpins where eagles soar below$sr$
  union all
  select $sr$southern-winery-escape$sr$, $sr$demir-kapija-gorge$sr$, 0::smallint, $sr$Застанете таму каде што Вардар ја пробил планината$sr$, $sr$Stand where the Vardar broke through the mountain$sr$
  union all
  select $sr$southern-winery-escape$sr$, $sr$popova-kula-winery$sr$, 1::smallint, $sr$Уживајте во дегустација на зајдисонце над лозјата$sr$, $sr$Savor a sunset wine tasting overlooking the vines$sr$
  union all
  select $sr$pelister-peaks-hike$sr$, $sr$pelister-viewpoint$sr$, 0::smallint, $sr$Гледајте како светот паѓа од работ на Баба Планина$sr$, $sr$Watch the world fall away at Baba Mountain's edge$sr$
  union all
  select $sr$pelister-peaks-hike$sr$, $sr$pelister-national-park$sr$, 1::smallint, $sr$Искачете се до ледничките Очи што го одразуваат бесконечното небо$sr$, $sr$Hike to the glacial 'Eyes' that reflect infinite sky$sr$
  union all
  select $sr$prespa-hidden-shores$sr$, $sr$prespa-lake-shore$sr$, 0::smallint, $sr$Гледајте ги пеликаните како цртаат кругови на утринското небо$sr$, $sr$Watch pelicans paint circles in the morning sky$sr$
  union all
  select $sr$prespa-hidden-shores$sr$, $sr$golem-grad-island$sr$, 1::smallint, $sr$Шетајте меѓу римски урнатини чувани од древни змии$sr$, $sr$Walk among Roman ruins guarded by ancient serpents$sr$
) src (route_slug, slug, position, things_mk, things_en)
  join public.routes r on r.slug = src.route_slug and r.updated_by is null
  join public.spots s on s.slug = src.slug
  on conflict (route_id, spot_id) do update set
    position = excluded.position,
    things_to_do_mk = excluded.things_to_do_mk,
    things_to_do_en = excluded.things_to_do_en
  where exists (
    select 1 from public.routes r
    where r.id = public.route_spots.route_id
      and r.updated_by is null
  );

  -- No photo manifest yet. Files stay on the static host when the manifest lands.
end;
$seed$;

revoke all on function public.apply_content_seed_v1() from public, anon, authenticated;

select public.apply_content_seed_v1();

do $$
begin
  assert (select count(*) from public.spots) = 36, 'spots != 36';
  assert (select count(*) from public.routes) = 7, 'routes != 7';
  assert (select count(*) from public.route_spots) = 16, 'route_spots != 16';
  assert (
    select count(*) from public.spots
    where slug = 'vodoca-monastery' and status = 'draft'
  ) = 1, 'spot 36 missing';
  assert not exists (select 1 from public.spots where mk_status = 'missing'), 'MK missing on a spot';
  assert not exists (select 1 from public.routes where mk_status = 'missing'), 'MK missing on a route';
  assert not exists (select 1 from public.spots where status = 'published'), 'machine MK must stay draft';
  assert not exists (select 1 from public.routes where status = 'published'), 'machine routes must stay draft';
end $$;
